head.b:skin:
* {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    margin: 0;
    padding: 0;
    background:
        radial-gradient(
            circle at 50% -10%,
            #41436A 0%,
            #2a3950 45%,
            #151d2a 100%
        );
    color: #ffffff;
    font-family: 'Noto Sans Devanagari', sans-serif;
    min-height: 100vh;
}

body, button, input {
    font-family: 'Noto Sans Devanagari', sans-serif;
}

button {
    -webkit-tap-highlight-color: transparent;
}

::-webkit-scrollbar {
    width: 7px;
}

::-webkit-scrollbar-track {
    background: #1a2332;
}

::-webkit-scrollbar-thumb {
    background: #41436A;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #e98006;
}

#Blog1, .blog-posts, .blog-pager, .blog-feeds, .post-outer, .widget {
    display: none !important;
}

.seo-crawler-indexing {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    padding: 0 !important;
    margin: -1px !important;
    overflow: hidden !important;
    clip: rect(0, 0, 0, 0) !important;
    white-space: nowrap !important;
    border: 0 !important;
}

.bhajasi-root {
    min-height: 100vh;
}

.bhajasi-app {
    min-height: 100vh;
    max-width: 760px;
    margin: auto;
    padding-bottom: 78px;
}

/* Header */
.bhajasi-header {
    position: sticky;
    top: 0;
    z-index: 50;
    background: rgba(42, 57, 80, 0.96);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border-bottom: 1px solid rgba(233, 128, 6, 0.25);
    padding: 6px 15px 5px;
}

.bhajasi-brandline {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
}

.bhajasi-brand-container {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
    padding: 2px 0;
}

.bhajasi-header-logo {
    width: 38px;
    height: 38px;
    min-width: 38px;
    min-height: 38px;
    object-fit: contain;
    border-radius: 50%;
    filter: drop-shadow(0 2px 5px rgba(0,0,0,0.3));
}

/* Brand Group */
.bhajasi-brand-group {
    display: flex;
    flex-direction: column;
    min-width: 0;
    padding-top: 5px;
    padding-bottom: 1px;
    margin: 0;
    overflow: visible;
}

.bhajasi-brand-wrapper {
    display: inline-flex;
    align-items: baseline;
    gap: 3px;
    line-height: 1.4;
    min-height: auto;
    margin: 0;
    padding: 0;
    overflow: visible;
}

.bhajasi-brand {
    margin: 0;
    padding: 3px 2px 2px;
    font-family: 'Alkatra', cursive;
    font-size: 17.5px;
    line-height: 1.4;
    display: inline-block;
    overflow: visible;
    font-weight: 600;
    letter-spacing: 0.5px;
    white-space: nowrap;
    background: linear-gradient(135deg, #fbd52d 0%, #e98006 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
}

.brand-domain {
    font-family: 'Alkatra', cursive;
    font-size: 10.5px;
    font-weight: 700;
    color: #ffffff;
    opacity: 0.9;
    letter-spacing: 0.5px;
    margin-bottom: 0;
}

.bhajasi-tagline {
    color: #cbd5e1;
    font-size: 9.5px;
    margin-top: 0;
    line-height: 1.15;
    white-space: nowrap;
    letter-spacing: 0.2px;
}

.bhajasi-action-group {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 3px;
}

.bhajasi-credit {
    color: #cbd5e1;
    font-size: 10px;
    font-weight: 600;
}

.bhajasi-social-btns {
    display: flex;
    align-items: center;
    gap: 6px;
}

.bhajasi-header-btn {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 3px 8px;
    border-radius: 6px;
    font-size: 10.5px;
    font-weight: 600;
    border: 1px solid rgba(233, 128, 6, 0.4);
    background: rgba(65, 67, 106, 0.7);
    color: #fbd52d;
    cursor: pointer;
    text-decoration: none;
    transition: all 0.2s ease;
}

.bhajasi-header-btn:hover {
    background: #e98006;
    color: #2a3950;
}

.bhajasi-whatsapp-btn {
    border-color: rgba(37, 211, 102, 0.35);
    background: rgba(37, 211, 102, 0.12);
    color: #25d366;
}

.bhajasi-whatsapp-btn:hover {
    background: #25d366;
    color: #ffffff;
}

.bhajasi-progress {
    height: 2.5px;
    background: #1a2332;
    margin: 6px -15px -6px;
}

.bhajasi-progress-bar {
    height: 100%;
    width: 0;
    background: linear-gradient(90deg, #fbd52d, #e98006);
    transition: width .25s ease;
}

.bhajasi-main {
    padding: 10px 16px 20px;
}

/* Sections */
.bhajasi-section {
    margin-bottom: 24px;
    border-radius: 18px;
    padding: 14px;
    border: 1px solid transparent;
}

.bhajasi-section-saints {
    background: rgba(30, 42, 60, 0.75);
    border-color: rgba(65, 67, 106, 0.95);
    box-shadow: 0 4px 18px rgba(0, 0, 0, 0.3);
}

.bhajasi-section-works {
    background: rgba(152, 64, 99, 0.24);
    border-color: rgba(152, 64, 99, 0.65);
}

.bhajasi-section-themes {
    background: rgba(48, 197, 173, 0.12);
    border-color: rgba(48, 197, 173, 0.45);
}

.bhajasi-section-title {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin: 2px 4px 12px;
}

.bhajasi-section-title h2,
.bhajasi-section-title h3 {
    margin: 0;
    font-family: 'Tiro Devanagari Marathi', serif;
    font-size: 20px;
    line-height: 1.3;
    font-weight: 700;
    letter-spacing: 0.02em;
}

.bhajasi-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
}

.bhajasi-card {
    width: 100%;
    text-align: left;
    background: linear-gradient(145deg, #2a3950, #1c2738);
    border: 1px solid rgba(65, 67, 106, 0.8);
    border-radius: 15px;
    padding: 14px;
    cursor: pointer;
    color: #ffffff;
    transition: border-color .2s ease, transform .2s ease, background .2s ease;
}

.bhajasi-card:hover {
    border-color: #e98006;
    transform: translateY(-2px);
    background: linear-gradient(145deg, #324460, #222f44);
}

.bhajasi-card-title {
    font-family: 'Khand', sans-serif;
    font-size: 18px;
    font-weight: 600;
    line-height: 1.35;
    color: #ffffff;
    letter-spacing: 0.02em;
}

.bhajasi-card-sub {
    margin-top: 4px;
    color: #cbd5e1;
    font-size: 11px;
    line-height: 1.5;
    font-family: 'Noto Sans Devanagari', sans-serif;
}

.bhajasi-saint-card { min-height: 72px; }
.bhajasi-work-card { min-height: 76px; }
.bhajasi-theme-card { min-height: 70px; }

.bhajasi-empty {
    grid-column: 1 / -1;
    border: 1px dashed rgba(233, 128, 6, 0.35);
    border-radius: 14px;
    padding: 22px;
    color: #cbd5e1;
    text-align: center;
    font-size: 13.5px;
    background: rgba(26, 35, 50, 0.4);
}

.bhajasi-reader-head {
    padding: 1px 1px 14px;
}

.bhajasi-reader-nav {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding-bottom: 12px;
}

.bhajasi-back {
    border: 0;
    background: transparent;
    color: #e98006;
    padding: 0;
    cursor: pointer;
    font-size: 13px;
    font-weight: 600;
}

.bhajasi-day-label {
    color: #e98006;
    font-size: 12px;
    font-weight: 700;
    white-space: nowrap;
    font-family: 'Noto Sans Devanagari', sans-serif;
}

.bhajasi-title-row {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 12px;
}

.bhajasi-title {
    margin: 0;
    color: #ffffff;
    font-family: 'Tiro Devanagari Marathi', serif;
    font-size: 26px;
    line-height: 1.3;
    font-weight: 700;
    letter-spacing: 0.015em;
}

/* Verse Card */
.bhajasi-verse {
    position: relative;
    overflow: hidden;
    background: linear-gradient(155deg, #2a3950, #1b2535);
    border: 1px solid rgba(65, 67, 106, 0.7);
    border-radius: 16px;
    padding: 16px 14px 14px;
    margin: 12px 0;
    box-shadow: 0 4px 18px rgba(0,0,0,0.25);
}

.bhajasi-verse::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image: url('https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEgUkMlQ2VCBA3DRDc8a3Qu89Rj91lhI_IQdYMui5Pik3SYf7exN0DPTHaqnxbHfsYZYVhu5yknjRkgw87QXOfkAOmlVKVge-LUv1JZdBs8MF0HR5Ewp8N26g_FuH7m9m2HzzVj0PVSrjVbBIM5BNZtH4TqR_ybA1VO0vkBHifpF_ftC6TqlLTHOEIlJTniT/s512/light%20bhajasi%20White%20Spiral%20Logo%20with%20Golden%20Dot.png');
    background-position: center;
    background-repeat: no-repeat;
    background-size: 185px auto;
    opacity: .045;
    pointer-events: none;
}
.bhajasi-verse > * {
    position: relative;
    z-index: 1;
}

.bhajasi-verse-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 10px;
    padding-bottom: 6px;
    border-bottom: 1px dashed rgba(255,255,255,0.08);
}

.bhajasi-verse-badge {
    font-size: 12px;
    font-weight: 700;
    color: #fcffcd;
    font-family: 'Tiro Devanagari Marathi', serif;
    letter-spacing: 0.03em;
}

.bhajasi-verse-wa-btn {
    border: 1px solid rgba(37, 211, 102, 0.45);
    background: rgba(37, 211, 102, 0.12);
    color: #25d366;
    border-radius: 99px;
    padding: 3px 9px;
    font-size: 10.5px;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    transition: all 0.2s ease;
}

.bhajasi-verse-wa-btn:hover {
    background: #25d366;
    color: #ffffff;
    transform: scale(1.02);
}

.bhajasi-verse-text {
    color: #ffffff;
    text-align: center;
    font-family: 'Laila', serif;
    font-size: 18.5px;
    line-height: 1.85;
    font-weight: 700;
}

.bhajasi-verse-line {
    display: block;
    margin: 2px 0;
    padding: 0;
}

.bhajasi-meaning {
    border-top: 1px solid rgba(65, 67, 106, 0.6);
    margin-top: 12px;
    padding-top: 10px;
    text-align: left;
}

.bhajasi-meaning-title {
    font-family: 'Noto Serif Devanagari', serif;
    color: #a0ea90;
    font-size: 11.5px;
    font-weight: 700;
    margin-bottom: 4px;
    letter-spacing: 0.02em;
}

.bhajasi-meaning-text {
    margin: 0;
    color: #cbd5e1;
    font-family: 'Noto Sans Devanagari', sans-serif;
    font-size: 13.5px;
    line-height: 1.8;
    font-weight: 400;
}

.bhajasi-teaching {
    border-top: 1px dashed rgba(48, 197, 173, 0.35);
    margin-top: 10px;
    padding-top: 8px;
    text-align: left;
}

.bhajasi-teaching-title {
    font-family: 'Noto Serif Devanagari', serif;
    color: #30c5ad;
    font-size: 11.5px;
    font-weight: 700;
    margin-bottom: 3px;
    letter-spacing: 0.02em;
}

.bhajasi-teaching-text {
    margin: 0;
    color: #f1f5f9;
    font-family: 'Playpen Sans', 'Noto Sans Devanagari', cursive, sans-serif;
    font-size: 13px;
    line-height: 1.8;
    font-weight: 500;
}

.bhajasi-reader-footer {
    display: flex;
    justify-content: space-between;
    margin-top: 12px;
}

.bhajasi-pager {
    width: 44px;
    height: 44px;
    border: 1px solid rgba(65, 67, 106, 0.8);
    background: #1c2738;
    color: #e98006;
    border-radius: 12px;
    cursor: pointer;
    font-size: 15px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}

.bhajasi-pager:hover:not(:disabled) {
    border-color: #e98006;
    background: #41436A;
    color: #ffffff;
}

.bhajasi-pager:disabled {
    opacity: .25;
    cursor: default;
}

.bhajasi-continue-list {
    display: grid;
    gap: 8px;
}

.bhajasi-continue-card {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 12px 14px;
    border: 1px solid rgba(65, 67, 106, 0.8);
    border-radius: 14px;
    background: linear-gradient(145deg, #2a3950, #1c2738);
    color: #ffffff;
    cursor: pointer;
    text-align: left;
    transition: all 0.2s ease;
}

.bhajasi-continue-card:hover {
    border-color: #e98006;
    transform: translateY(-1px);
}

.bhajasi-continue-main { min-width: 0; }
.bhajasi-continue-saint { color: #e98006; font-size: 10px; font-weight: 700; }
.bhajasi-continue-work { color: #ffffff; font-size: 15px; font-weight: 600; font-family: 'Khand', sans-serif; }
.bhajasi-continue-day { color: #cbd5e1; font-size: 10px; white-space: nowrap; }

/* Page Footer */
.bhajasi-page-footer {
    width: 100%;
    margin-top: 30px;
    padding: 16px 14px 22px;
    text-align: center;
    border-top: 1px solid rgba(233, 128, 6, 0.2);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.bhajasi-footer-inner {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    color: #e2e8f0;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.02em;
}

.bhajasi-footer-logo-box {
    width: 30px;
    height: 30px;
    padding: 3px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: #ffffff;
    border-radius: 8px;
    box-sizing: border-box;
    box-shadow: 0 2px 8px rgba(0,0,0,.18);
}

.bhajasi-footer-logo {
    width: 22px;
    height: 22px;
    object-fit: contain;
    border-radius: 50%;
}

.bhajasi-footer-sub {
    font-size: 10px;
    color: #94a3b8;
}


/* Pariksha — minimal question-first exam and certificate UI */
.bhajasi-exam-card {
    width: 100%;
    background: linear-gradient(145deg, #2a3950, #1c2738);
    border: 1px solid rgba(48,197,173,.38);
    border-radius: 16px;
    padding: 16px;
    box-shadow: 0 5px 20px rgba(0,0,0,.22);
}
.bhajasi-exam-meta {
    display: flex;
    gap: 7px;
    align-items: center;
    margin: 9px 0 12px;
    color: #94a3b8;
    font-size: 11px;
}
.bhajasi-primary-btn,
.bhajasi-secondary-btn,
.bhajasi-study-btn {
    border-radius: 10px;
    padding: 10px 14px;
    font-size: 12px;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    transition: all .18s ease;
}
.bhajasi-primary-btn {
    background: linear-gradient(135deg, #fbd52d, #e98006);
    color: #151d2a;
    border-color: #fbd52d;
}
.bhajasi-resume-btn {
    background: linear-gradient(135deg, #34d399, #0f9f78);
    color: #071b16;
    border-color: #52e0b7;
}
.bhajasi-resume-btn:hover:not(:disabled) {
    background: linear-gradient(135deg, #52e0b7, #18b887);
}
.bhajasi-primary-btn:hover:not(:disabled) { transform: translateY(-1px); }
.bhajasi-primary-btn:disabled,
.bhajasi-secondary-btn:disabled {
    opacity: .45;
    cursor: not-allowed;
}
.bhajasi-secondary-btn {
    background: rgba(65,67,106,.5);
    color: #e2e8f0;
    border-color: rgba(148,163,184,.28);
}
.bhajasi-exam-question h3 {
    margin: 13px 2px 14px;
    color: #fff;
    font-family: 'Tiro Devanagari Marathi', serif;
    font-size: 22px;
    line-height: 1.5;
}
.bhajasi-exam-progress {
    height: 5px;
    border-radius: 999px;
    background: #151d2a;
    overflow: hidden;
}
.bhajasi-exam-progress-bar {
    height: 100%;
    background: linear-gradient(90deg,#30c5ad,#fbd52d,#e98006);
}
.bhajasi-exam-options {
    display: grid;
    gap: 8px;
}
.bhajasi-exam-option {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    padding: 12px 13px;
    text-align: left;
    color: #e2e8f0;
    background: rgba(26,35,50,.72);
    border: 1px solid rgba(65,67,106,.8);
    border-radius: 13px;
    cursor: pointer;
    font-size: 13px;
    line-height: 1.45;
}
.bhajasi-exam-option.selected {
    color: #151d2a;
    background: rgba(251,213,45,.95);
    border-color: #fbd52d;
}
.bhajasi-exam-radio {
    width: 24px;
    height: 24px;
    min-width: 24px;
    border: 1px solid rgba(203,213,225,.4);
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
}
.bhajasi-study-card,
.bhajasi-learning-card {
    margin-top: 12px;
