.bhajasi-result-topic { color:#fbd52d; font-family:'Tiro Devanagari Marathi',serif; font-size:26px; line-height:1.35; font-weight:800; text-align:center; margin-bottom:12px; }\n.bhajasi-result-score { color: #fff; font-size: 40px; font-weight: 800; }
.bhajasi-result-percent { color: #fbd52d; font-size: 25px; font-weight: 800; margin-top: 3px; }
