}
.bhajasi-global-search-overlay {
    position: fixed;
    inset: 0;
    z-index: 300;
    display: flex;
    align-items: flex-start;
    justify-content: center;
    padding: 76px 14px 92px;
    background: rgba(9,15,24,.52);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
