}
.bhajasi-global-search-dialog {
    width: min(680px, 100%);
    max-height: min(760px, calc(100vh - 150px));
    display: flex;
    flex-direction: column;
    background: linear-gradient(145deg, #24334a, #172333);
    border: 1px solid rgba(251,213,45,.55);
    border-radius: 20px;
    box-shadow: 0 24px 70px rgba(0,0,0,.62);
