.bhajasi-breadcrumb span:last-child { color: #e98006; }

body.script:
//

const SAINTS_BASE =
    'https://raw.githubusercontent.com/project-bharat/bhajasi/main/data/saints/';
const DATA_BASE =
    'https://raw.githubusercontent.com/project-bharat/bhajasi/main/data/';
const NITYA_BASE =
    DATA_BASE + 'nitya-pathan/';
const PARIKSHA_BASE =
    DATA_BASE + 'pariksha/';
const SITE_URL =
    'https://bhajasibharat.blogspot.com/';
const SITE_LOGO =
    'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEg94LhEYUGaBU0HdY5Cumz3j-nmJ7NdDjBQ5DCKsZd5uBYDTKYFHgQGZ5Iik5cJoBJ2r4pntUVQDJVTI2SvvraMlgW0PVtCOcsx7ebdj2ILBLVEq-nPNy_sfukMA1GE7xfmr28iOBA3JfPy0BJNx08R_DaB6ncp6EFpkJ_o_IyAWZuD6QaTeN4BSMZ_cLkq/s1600/light%20bhajasi%20White%20Spiral%20Logo%20with%20Golden%20Dot.png';

// Unified Single Constant used for both snap card and UI footer
const FOOTER_LOGO =
    'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiQsnusVJ6kB8gTAULrKk9JaNddwvwUlw4-6HEZNIiF12IvKnbMAOwdUMrlevN5EKYgnl6LHpKvFZjlDqgZ9WvpNu_rjPzJ473O1rrL9iG_eD4VxA_EZKj2uN_DmIXTzZTKa3kaaB0p821aftNpRXTRZAqZQPqniktfZkVslxDAGMUkP5b3G4cOyAFYpVMn/s1600/dark%20bhajasi%20fevicon192.png';

const PROGRESS_KEY = 'bhajasi_reading_progress_v2';
const NOTIFY_KEY = 'bhajasi_notification_v1';
const EXAM_RESULT_KEY = 'bhajasi_pariksha_results_v1';
const EXAM_PROGRESS_KEY = 'bhajasi_pariksha_progress_v1';

const {
    useState,
    useEffect,
    useMemo,
    useRef
} = React;

const CONTENT_KEYS = [
    'entries',
    'verses',
    'ovis',
    'abhangs',
    'shloks',
    'stanzas'
];

function safeJSON(value, fallback) {
    try {
        return JSON.parse(value);
    } catch (e) {
        return fallback;
    }
}

function readProgress() {
    return safeJSON(localStorage.getItem(PROGRESS_KEY) || '{}', {});
}

function readExamProgress() {
    return safeJSON(localStorage.getItem(EXAM_PROGRESS_KEY) || '{}', {});
}

function getExamQuestionKey(question, index) {
    if (question && question.id !== undefined && question.id !== null && String(question.id).trim()) {
        return String(question.id);
    }
    if (question && question.questionId !== undefined && question.questionId !== null && String(question.questionId).trim()) {
        return String(question.questionId);
    }
    return 'index:' + String(index);
}

function persistExamProgress(exam, questions, questionIndex, answers, startedAt) {
    if (!exam || !exam.id) return;
    const progress = readExamProgress();
    const questionIds = (questions || []).map(function(question, index) {
        return getExamQuestionKey(question, index);
    });
    const existing = progress[exam.id] || {};
    progress[exam.id] = {
        examId: exam.id,
        title: exam.title || '',
        file: exam.file || '',
        questionIds: questionIds,
        currentQuestionIndex: Math.max(0, Math.min(Number(questionIndex || 0), Math.max(0, questionIds.length - 1))),
        answers: Object.assign({}, answers || {}),
        startedAt: startedAt || existing.startedAt || new Date().toISOString(),
        updatedAt: new Date().toISOString()
    };
    localStorage.setItem(EXAM_PROGRESS_KEY, JSON.stringify(progress));
}

function clearExamProgress(examId) {
    if (!examId) return;
    const progress = readExamProgress();
    if (progress[examId]) {
        delete progress[examId];
        localStorage.setItem(EXAM_PROGRESS_KEY, JSON.stringify(progress));
    }
}

function writeProgress(key, value) {
    const old = readProgress();
    old[key] = Object.assign({}, old[key] || {}, value);
    localStorage.setItem(PROGRESS_KEY, JSON.stringify(old));
}

function makeWorkKey(saint, work) {
    return String(saint && saint.id || '') + '::' +
        String(work && (work.id || work.file || work.title) || '');
}

function toMarathiDigits(num) {
    if (num === null || num === undefined || num === '') return '';
    const digits = ['०','१','२','३','४','५','६','७','८','९'];
    return String(num).replace(/[0-9]/g, function(d) {
        return digits[d];
    });
}

function getVerseLabel(entry, index, work) {
    if (!entry) return '';
    if (entry.label || entry.typeLabel) {
        return entry.label || entry.typeLabel;
    }

    let value = '';
    if (entry.number !== undefined && entry.number !== null) {
        value = toMarathiDigits(entry.number);
    } else if (entry.id) {
        const match = String(entry.id).match(/(\d+)$/);
        if (match) value = toMarathiDigits(parseInt(match[1], 10));
    }
    if (!value) {
        const textMatch = String(entry.text || '').match(
            /॥\s*([०-९0-9]+(?:-[०-९0-9]+)?)\s*॥/u
        );
        if (textMatch) value = toMarathiDigits(textMatch[1]);
    }
    if (!value) value = toMarathiDigits(index + 1);

    const type = String(
        entry.type ||
        entry.kind ||
        (work && work.type) ||
        ''
    ).toLowerCase();

    if (type.indexOf('अभंग') >= 0 || type.indexOf('abhang') >= 0) return 'अभंग ' + value;
    if (type.indexOf('श्लोक') >= 0 || type.indexOf('shlok') >= 0 || type.indexOf('स्तोत्र') >= 0) return 'श्लोक ' + value;
    if (type.indexOf('पद') >= 0 || type.indexOf('pad') >= 0) return 'पद ' + value;
    if (type.indexOf('दोहा') >= 0 || type.indexOf('doha') >= 0) return 'दोहा ' + value;
    if (type.indexOf('ओवी') >= 0 || type.indexOf('ovi') >= 0 || type.indexOf('ग्रंथ') >= 0) return 'ओवी ' + value;

    return 'रचना ' + value;
}

function splitPoem(text) {
    if (!text) return [];
    const normalized = String(text).replace(/\r\n/g, '\n').trim();
    if (!normalized) return [];

    const lines = normalized.split('\n').map(function(line) { return line.trim(); }).filter(Boolean);
    if (lines.length > 1) return lines;

    const clauses = normalized.split(/(?<=।)\s+/u).map(function(x) { return x.trim(); }).filter(Boolean);
    if (clauses.length <= 2) return clauses;

    const grouped = [];
    for (let i = 0; i < clauses.length; i += 2) {
        grouped.push(clauses.slice(i, i + 2).join(' '));
    }
    return grouped;
}

function normalizeContent(raw) {
    if (Array.isArray(raw)) return { entries: raw, days: 1 };
    if (!raw || typeof raw !== 'object') return { entries: [], days: 1 };

    let entries = [];
    CONTENT_KEYS.some(function(key) {
        if (Array.isArray(raw[key])) {
            entries = raw[key];
            return true;
        }
        return false;
    });

    if (!entries.length && Array.isArray(raw.content)) {
        entries = raw.content;
    }

    return Object.assign({}, raw, {
        entries: entries,
        days: Number(raw.days || 1)
    });
}

async function fetchJSON(url) {
    const response = await fetch(
        url + (url.indexOf('?') >= 0 ? '&' : '?') + 'v=' + Date.now(),
        {
            cache: 'no-store',
            headers: { 'Accept': 'application/json' }
        }
    );
    if (!response.ok) throw new Error('HTTP ' + response.status + ': ' + url);
    return response.json();
}

function resolveURL(kind, file) {
    if (!file) return '';
    if (/^https?:\/\//i.test(file)) return file;
    if (kind === 'nitya') return NITYA_BASE + file.replace(/^nitya-pathan\//, '');
    return SAINTS_BASE + file.replace(/^saints\//, '');
}

function workHasSections(work) {
    return !!(work && Array.isArray(work.sections) && work.sections.length);
}

function getSectionDisplaySubtitle(section) {
    if (!section) return '';
    return String(
        section.subtitle ||
        section.name ||
        section.description ||
        section.topic ||
        ''
    ).trim();
}

function getWorkSummary(work) {
    if (!work) return '';
    if (work.description) return work.description;
    if (work.type) return work.type;
    if (work.days) return 'दिवस ' + toMarathiDigits(work.days);
    if (work.sections) return toMarathiDigits(work.sections.length) + ' विभाग';
    return '';
}

function formatSubTitle(title, parentTitle) {
    if (!title) return '';
    if (parentTitle && title.indexOf(parentTitle) === 0) {
        return title.replace(
            new RegExp('^' + parentTitle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*[-—–]?\\s*', 'u'),
            ''
        ).trim() || title;
    }
    return title;
}

/* Metadata-aware title used by the reader and image shares. */
function getReaderTitle(work, parentWork) {
    if (!work) return '';
    const baseTitle = String(work.title || '').trim();
    const subtitle = String(work.subtitle || '').trim();
    if (subtitle) return baseTitle + ' – ' + subtitle;
    return baseTitle;
}

function flattenContentForSearch(content) {
    const data = normalizeContent(content);
    return data.entries.map(function(entry, index) {
        return {
            entry: entry,
            index: index,
            text: [
                entry.text,
                entry.meaning,
                entry.teaching,
                entry.commentary,
                entry.translation
            ].filter(Boolean).join(' ')
        };
    });
}

function entryBelongsToDay(entry, day) {
    if (entry.day === undefined || entry.day === null || entry.day === '') {
        return Number(day) === 1;
    }
    return Number(entry.day) === Number(day);
}

function getEntriesForDay(content, day) {
    const data = normalizeContent(content);
    if (!data.entries.length) return [];
    const hasDayData = data.entries.some(function(entry) {
        return entry.day !== undefined && entry.day !== null;
    });
    if (!hasDayData) return data.entries;
    return data.entries.filter(function(entry) {
        return entryBelongsToDay(entry, day);
    });
}

function getTotalDays(work, content) {
    const data = normalizeContent(content);
    const fromWork = Number(work && work.days || 0);
    const fromContent = Number(data.days || 0);
    const entryDays = data.entries
        .map(function(entry) { return Number(entry.day || 0); })
        .filter(Boolean);
    const fromEntries = entryDays.length ? Math.max.apply(Math, entryDays) : 1;
    return Math.max(1, fromWork, fromContent, fromEntries);
}

function expandHaripath(entries, workTitle) {
    return entries || [];
}

function readNotifySettings() {
    return safeJSON(localStorage.getItem(NOTIFY_KEY) || '{}', {});
}

function saveNotifySettings(settings) {
    localStorage.setItem(NOTIFY_KEY, JSON.stringify(settings || {}));
}

function notificationSupported() {
    return 'Notification' in window;
}

function localDateKey(date) {
    const value = date instanceof Date ? date : new Date();
    const year = value.getFullYear();
    const month = String(value.getMonth() + 1).padStart(2, '0');
    const day = String(value.getDate()).padStart(2, '0');
    return year + '-' + month + '-' + day;
}

function getDailyNityaIndex(length) {
    if (!length) return 0;
    const start = new Date(new Date().getFullYear(), 0, 0);
    const now = new Date();
    const dayOfYear = Math.floor((now - start) / 86400000);
    return (dayOfYear - 1) % length;
}

function getProgressItems(saints) {
    const progress = readProgress();
    const result = [];

    (saints || []).forEach(function(saint) {
        (saint.works || []).forEach(function(work) {
            if (workHasSections(work)) {
                work.sections.forEach(function(section) {
                    const saved = progress[makeWorkKey(saint, section)];
                    if (saved) {
                        result.push({
                            saint: saint,
                            work: section,
                            parentWork: work,
                            day: Number(saved.day || 1),
                            updatedAt: Number(saved.updatedAt || 0)
                        });
                    }
                });
            } else {
                const saved = progress[makeWorkKey(saint, work)];
                if (saved) {
                    result.push({
                        saint: saint,
                        work: work,
                        parentWork: null,
                        day: Number(saved.day || 1),
                        updatedAt: Number(saved.updatedAt || 0)
                    });
                }
            }
        });
    });

    return result.sort(function(a, b) {
        return b.updatedAt - a.updatedAt;
    });
}

function topLevelWorks(saints) {
    return (saints || []).flatMap(function(saint) {
        return (saint.works || []).map(function(work, index) {
            return {
                saint: saint,
                work: work,
                index: index
            };
        });
    });
}

function getSaintCardSummary(saint) {
    return (saint && Array.isArray(saint.works) ? saint.works : [])
        .map(function(work) {
            return work && work.title ? work.title : '';
        })
        .filter(Boolean)
        .join(' • ');
}

function buildMetadataSearch(saints, nitya) {
    const results = [];

    (saints || []).forEach(function(saint) {
        results.push({
            type: 'saint',
            title: saint.name || saint.id,
            sub: 'संत • ग्रंथसूची',
            saint: saint
        });

        (saint.works || []).forEach(function(work) {
            results.push({
                type: 'work',
                title: work.title || work.id,
                sub: [saint.name, work.type].filter(Boolean).join(' • '),
                saint: saint,
                work: work
            });

            (work.sections || []).forEach(function(section) {
                results.push({
                    type: 'section',
                    title: section.title || section.id,
                    sub: [work.title, saint.name].filter(Boolean).join(' • '),
                    saint: saint,
                    work: section,
                    parentWork: work
                });
            });
        });
    });

    ((nitya && nitya.works) || []).forEach(function(work) {
        results.push({
            type: 'nitya',
            title: work.title || work.id,
            sub: ['नित्य पठण', work.type].filter(Boolean).join(' • '),
            nityaWork: work
        });
    });

    return results;
}

