    function navigate(nextView) {
        setView(nextView);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function openSaint(saint) {
        setSelectedSaint(saint);
        setSelectedParentWork(null);
        setSelectedWork(null);
        setSelectedContent(null);
        navigate('works');
    }

    async function loadWorkContent(work, kind) {
        if (!work) return null;
        const file = work.file;
        if (!file) return normalizeContent(work);

        const url = resolveURL(kind || 'saint', file);
        if (contentCache.current[url]) {
            return contentCache.current[url];
        }

        const data = normalizeContent(await fetchJSON(url));
        contentCache.current[url] = data;
        return data;
    }

    async function openWork(saint, work, initialDay, parentWork, kind) {
        if (!work) return;

        const targetKind = kind || 'saint';
        setWorkLoading(true);

        try {
            const content = await loadWorkContent(work, targetKind);
            const total = getTotalDays(work, content);
            const progress = readProgress();
            const saved = progress[makeWorkKey(saint || { id: targetKind }, work)];
            const requested = Number(initialDay || (saved && saved.day) || 1);
            const safeDay = Math.min(Math.max(1, requested), total);

            if (targetKind === 'nitya') {
                setSelectedNityaWork(work);
                setSelectedContent(content);
                setSelectedWork(null);
                setSelectedSaint(null);
                setSelectedParentWork(null);
                setDay(safeDay);
                navigate('nityaReader');
            } else {
                setSelectedSaint(saint);
                setSelectedParentWork(parentWork || null);
                setSelectedWork(work);
                setSelectedContent(content);
                setSelectedNityaWork(null);
                setDay(safeDay);
                writeProgress(
                    makeWorkKey(saint, work),
                    { day: safeDay, updatedAt: Date.now() }
                );
                navigate('reader');
            }
        } catch (error) {
            console.error('Bhajasi work loading error:', error);
            alert('हे साहित्य सध्या लोड करता आले नाही.');
        } finally {
            setWorkLoading(false);
        }
    }

    async function handleWorkClick(saint, work, parentWork) {
        if (!work) return;

        if (workHasSections(work)) {
            setSelectedSaint(saint);
            setSelectedParentWork(work);
            setSelectedWork(null);
            setSelectedContent(null);
            navigate('sections');
            return;
        }

        await openWork(saint, work, 1, parentWork || null, 'saint');
    }

    function openNityaList() {
        setSelectedNityaWork(null);
        setSelectedContent(null);
        navigate('nitya');
    }

    function openParikshaList() { navigate('pariksha'); }

    async function startExam(examMeta) {
        if (!examMeta || !examMeta.file) return;
        try {
            const bank = await fetchJSON(PARIKSHA_BASE + examMeta.file.replace(/^pariksha\//, ''));
            const questions = Array.isArray(bank.questions) ? bank.questions : [];
            const fullExam = Object.assign({}, examMeta, bank);
            const allProgress = readExamProgress();
            const savedProgress = allProgress[examMeta.id] || null;
            const validAnswers = {};

            if (savedProgress && savedProgress.answers && Array.isArray(savedProgress.questionIds)) {
                questions.forEach(function(question, index) {
                    const key = getExamQuestionKey(question, index);
                    if (savedProgress.answers[key] !== undefined) {
                        validAnswers[key] = savedProgress.answers[key];
                    }
                });
            }

            const restoredIndex = savedProgress && Number.isFinite(Number(savedProgress.currentQuestionIndex))
                ? Number(savedProgress.currentQuestionIndex)
                : 0;
            const safeIndex = questions.length
                ? Math.max(0, Math.min(restoredIndex, questions.length - 1))
                : 0;
            const startedAt = savedProgress && savedProgress.startedAt
                ? savedProgress.startedAt
                : new Date().toISOString();

            setSelectedExam(fullExam);
            setExamQuestions(questions);
            setExamQuestionIndex(safeIndex);
            setExamAnswers(validAnswers);
            setExamSubmitted(false);
            setExamResult(null);
            setCertificateName('');
            setCertificatePreview('');
            setCertificateId('');
            setExamSourceReturn(false);

            if (questions.length) {
                persistExamProgress(fullExam, questions, safeIndex, validAnswers, startedAt);
            }
            navigate('exam');
        } catch (error) {
            console.error('Bhajasi exam loading error:', error);
            alert('परीक्षा सध्या लोड करता आली नाही.');
        }
    }

    function selectExamAnswer(optionIndex) {
        if (examSubmitted || !examQuestions.length || !selectedExam) return;
        const question = examQuestions[examQuestionIndex];
        const key = getExamQuestionKey(question, examQuestionIndex);
        const nextAnswers = Object.assign({}, examAnswers, { [key]: optionIndex });
        setExamAnswers(nextAnswers);
        persistExamProgress(selectedExam, examQuestions, examQuestionIndex, nextAnswers, null);
    }

    function changeExamQuestion(nextIndex) {
        if (!examQuestions.length || !selectedExam) return;
        const safeIndex = Math.max(0, Math.min(Number(nextIndex), examQuestions.length - 1));
        setExamQuestionIndex(safeIndex);
        persistExamProgress(selectedExam, examQuestions, safeIndex, examAnswers, null);
    }

    function submitExam() {
        if (!examQuestions.length || !selectedExam) return;
        const unanswered = examQuestions.some(function(q, index) {
            return examAnswers[getExamQuestionKey(q, index)] === undefined;
        });
        if (unanswered) { alert('सर्व प्रश्नांची उत्तरे निवडा.'); return; }
        let score = 0;
        examQuestions.forEach(function(q, index) {
            const key = getExamQuestionKey(q, index);
            if (Number(examAnswers[key]) === Number(q.answer)) score += 1;
        });
        const percentage = Math.round((score / examQuestions.length) * 100);
        const passed = percentage >= Number(selectedExam && selectedExam.passingPercentage || 80);
        const result = { score:score, total:examQuestions.length, percentage:percentage, passed:passed, completedAt:new Date().toISOString() };
        setExamSubmitted(true);
        setExamResult(result);
        const saved = safeJSON(localStorage.getItem(EXAM_RESULT_KEY) || '{}', {});
        saved[selectedExam.id] = result;
        localStorage.setItem(EXAM_RESULT_KEY, JSON.stringify(saved));
        clearExamProgress(selectedExam.id);
        navigate('examResult');
    }

    function retryExam() {
        if (selectedExam) clearExamProgress(selectedExam.id);
        setExamQuestionIndex(0);
        setExamAnswers({});
        setExamSubmitted(false);
        setExamResult(null);
        if (selectedExam && examQuestions.length) {
            persistExamProgress(selectedExam, examQuestions, 0, {}, new Date().toISOString());
        }
        navigate('exam');
    }

    function makeCertificateId() {
        return 'BB-PAR-' + localDateKey(new Date()).replace(/-/g, '') + '-' + Math.random().toString(36).slice(2,7).toUpperCase();
    }

    function findExamSource(source) {
        if (!source || source.type === 'nitya') return null;
        const saint = saints.find(function(item){ return item.id === source.saintId; });
        if (!saint) return null;
        let found = null;
        (saint.works || []).some(function(work) {
            if (work.id === source.workId) { found={saint:saint,work:work,parentWork:null}; return true; }
            const section=(work.sections || []).find(function(item){ return item.id===source.entryId || item.id===source.workId; });
            if(section && section.file){ found={saint:saint,work:section,parentWork:work}; return true; }
            return false;
        });
        return found;
    }

    function getExamQuestionShareURL(exam, questionIndex) {
        try {
            const url = new URL(window.location.href);
            url.searchParams.set('bhajasiExam', String(exam && exam.id || ''));
            url.searchParams.set('bhajasiQuestion', String(Number(questionIndex) || 0));
            return url.toString();
        } catch (error) {
            return window.location.href;
        }
    }

    async function openSharedExamQuestion(examId, questionIndex) {
        if (!examId || !pariksha || !Array.isArray(pariksha.exams)) return false;
        const examMeta = pariksha.exams.find(function(exam){ return String(exam && exam.id || '') === String(examId); });
        if (!examMeta || !examMeta.file) return false;
        try {
            const bank = await fetchJSON(PARIKSHA_BASE + examMeta.file.replace(/^pariksha\//, ''));
            const questions = Array.isArray(bank.questions) ? bank.questions : [];
            if (!questions.length) return false;
            const safeIndex = Math.max(0, Math.min(Number(questionIndex) || 0, questions.length - 1));
            const fullExam = Object.assign({}, examMeta, bank);
            const savedProgress = readExamProgress()[examMeta.id] || null;
            const savedAnswers = savedProgress && savedProgress.answers ? savedProgress.answers : {};
            setSelectedExam(fullExam);
            setExamQuestions(questions);
            setExamQuestionIndex(safeIndex);
            setExamAnswers(Object.assign({}, savedAnswers));
            setExamSubmitted(false);
            setExamResult(null);
            setCertificateName('');
            setCertificatePreview('');
            setCertificateId('');
            setExamSourceReturn(false);
            navigate('exam');
            return true;
        } catch (error) {
            console.error('Bhajasi shared exam question error:', error);
            return false;
        }
    }

    async function shareExamQuestion(question, questionIndex) {
        if (!question || !selectedExam) return;

        const shareURL = getExamQuestionShareURL(selectedExam, questionIndex);
        const questionText = String(question.question || '').trim();
        const options = (question.options || []).map(function(option, index) {
            return String.fromCharCode(65 + index) + ') ' + String(option || '');
        });

        const shareText =
            'भजसी भारत .com (संतवाणी • ग्रंथ • हरिनाम • चिंतन • स्तोत्र)\n' +
            (selectedExam.title || 'ज्ञान प्रमाणपत्र परीक्षा') + '\n' +
            'प्रश्न: ' + questionText + '\n\n' +
            'पर्याय:\n' + options.join('\n') + '\n\n' +
            'प्रश्न सोडवा: ' + shareURL;

        const width = 1080;
        const padding = 76;
        const contentWidth = width - padding * 2;
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            alert('फोटो तयार करता आला नाही.');
            return;
        }

        if (document.fonts && document.fonts.ready) {
            try {
                await document.fonts.ready;
                await Promise.all([
                    document.fonts.load('700 42px "Tiro Devanagari Marathi"'),
                    document.fonts.load('700 42px "Laila"'),
                    document.fonts.load('400 30px "Noto Sans Devanagari"'),
                    document.fonts.load('700 34px "Noto Serif Devanagari"'),
                    document.fonts.load('700 30px "Alkatra"')
                ]);
            } catch (e) {}
        }

        function wrap(textValue, font, maxWidth) {
            if (!textValue) return [];
            ctx.font = font;
            const words = String(textValue).split(/\s+/u);
            const result = [];
            let current = '';
            words.forEach(function(word) {
                if (!word) return;
                const candidate = current ? current + ' ' + word : word;
                if (ctx.measureText(candidate).width > maxWidth && current) {
                    result.push(current);
                    current = word;
                } else {
                    current = candidate;
                }
            });
            if (current) result.push(current);
            return result;
        }

        const questionLines = wrap(
            questionText,
            '700 42px "Laila", "Noto Serif Devanagari", serif',
            contentWidth
        );

        const optionLines = [];
        options.forEach(function(option) {
            wrap(
                option,
                '400 34px "Noto Sans Devanagari", sans-serif',
                contentWidth - 38
            ).forEach(function(line, lineIndex) {
                optionLines.push((lineIndex === 0 ? '' : '   ') + line);
            });
        });

        const questionBlock = Math.max(questionLines.length, 1) * 66;
        const optionBlock = Math.max(optionLines.length, 1) * 56;
        const footerBlock = 205;
        const topBlock = 335;
        const height = Math.max(
            1200,
            topBlock + questionBlock + 120 + optionBlock + footerBlock + 90
        );

        canvas.width = width;
        canvas.height = height;

        /* Same share-card background and frame as the literature content snap. */
        const gradient = ctx.createLinearGradient(0, 0, width, height);
        gradient.addColorStop(0, '#2a3950');
        gradient.addColorStop(0.48, '#1e2838');
        gradient.addColorStop(1, '#151d2a');
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, width, height);

        const frameGradient = ctx.createLinearGradient(0, 24, width, height - 24);
        frameGradient.addColorStop(0, '#ffcf33');
        frameGradient.addColorStop(0.24, '#f59e0b');
        frameGradient.addColorStop(0.50, '#fff0a3');
        frameGradient.addColorStop(0.72, '#e98006');
        frameGradient.addColorStop(1, '#ffd24a');
        ctx.strokeStyle = frameGradient;
        ctx.lineWidth = 4;
        ctx.beginPath();
        if (ctx.roundRect) {
            ctx.roundRect(18, 18, width - 36, height - 36, 25);
        } else {
            ctx.rect(18, 18, width - 36, height - 36);
        }
        ctx.stroke();

        ctx.save();
        ctx.globalAlpha = 0.32;
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 1;
        ctx.beginPath();
        if (ctx.roundRect) {
            ctx.roundRect(21, 21, width - 42, height - 42, 22);
        } else {
            ctx.rect(21, 21, width - 42, height - 42);
        }
        ctx.stroke();
        ctx.restore();

        /* White/light logo watermark — intentionally different from the dark footer logo. */
        const watermarkImg = await loadLogoImage(SITE_LOGO);
        if (watermarkImg && watermarkImg.naturalWidth) {
            const wmSize = 440;
            const ratio = watermarkImg.naturalWidth / Math.max(1, watermarkImg.naturalHeight);
            const wmW = wmSize;
            const wmH = wmSize / Math.max(0.1, ratio);
            ctx.save();
            ctx.globalAlpha = 0.075;
            ctx.globalCompositeOperation = 'screen';
            ctx.drawImage(
                watermarkImg,
                (width - wmW) / 2,
                (height - wmH) / 2 - 35,
                wmW,
                wmH
            );
            ctx.restore();
        }

        /* Same header hierarchy as the literature share card. */
        ctx.textAlign = 'center';
        ctx.textBaseline = 'alphabetic';
        /* Main title */
        ctx.textAlign = 'center';
        ctx.fillStyle = '#e98006';
        ctx.font = '700 38px "Tiro Devanagari Marathi", serif';
        ctx.fillText('ज्ञान प्रमाणपत्र परीक्षा', width / 2, 105);

        /* Exam + question label in the same outlined-pill treatment. */
        const examTitle = String(selectedExam.title || 'परीक्षा');
        const subLabelText = examTitle + ' • प्रश्न';
        ctx.font = '700 27px "Noto Sans Devanagari", sans-serif';
        const subLabelW = ctx.measureText(subLabelText).width;
        const subBoxW = Math.min(contentWidth - 60, subLabelW + 64);
        const subBoxH = 56;
        const subBoxX = (width - subBoxW) / 2;
        const subBoxY = 130;
        const labelGradient = ctx.createLinearGradient(
            subBoxX, subBoxY, subBoxX + subBoxW, subBoxY + subBoxH
        );
        labelGradient.addColorStop(0, '#f6a80b');
        labelGradient.addColorStop(0.5, '#ffd45a');
        labelGradient.addColorStop(1, '#e98006');
        ctx.strokeStyle = labelGradient;
        ctx.lineWidth = 2.5;
        ctx.fillStyle = 'rgba(65,67,106,.45)';
        ctx.beginPath();
        if (ctx.roundRect) {
            ctx.roundRect(subBoxX, subBoxY, subBoxW, subBoxH, 15);
        } else {
            ctx.rect(subBoxX, subBoxY, subBoxW, subBoxH);
        }
        ctx.fill();
        ctx.stroke();

        ctx.fillStyle = '#ffffff';
        ctx.fillText(subLabelText, width / 2, subBoxY + 38);

        let y = 250;

        /* Question — the only content replacing the literature verse. */
        ctx.textAlign = 'left';
        ctx.fillStyle = '#fbd52d';
        ctx.font = '700 29px "Noto Sans Devanagari", sans-serif';
        ctx.fillText('प्रश्न:', padding, y);
        y += 60;

        ctx.fillStyle = '#ffffff';
        ctx.font = '700 42px "Laila", "Noto Serif Devanagari", serif';
        questionLines.slice(0, 5).forEach(function(line) {
            ctx.fillText(line, padding, y);
            y += 66;
        });

        /* Separator between question and options. */
        y += 12;
        ctx.strokeStyle = 'rgba(148,163,184,.30)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(width - padding, y);
        ctx.stroke();
        y += 48;

        ctx.fillStyle = '#63d6b5';
        ctx.font = '700 29px "Noto Sans Devanagari", sans-serif';
        ctx.fillText('पर्याय:', padding, y);
        y += 52;

        ctx.fillStyle = '#e8edf4';
        ctx.font = '400 34px "Noto Sans Devanagari", sans-serif';
        optionLines.slice(0, 12).forEach(function(line) {
            ctx.fillText(line, padding + (line.indexOf('   ') === 0 ? 30 : 0), y);
            y += 56;
        });

        /* Same footer strip and footer branding as the literature content snap. */
        const footerStripY = height - 196;
        ctx.fillStyle = '#0d1624';
        ctx.fillRect(24, footerStripY, width - 48, 172);

        const footerY = height - 176;
        ctx.strokeStyle = 'rgba(148,163,184,.25)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(padding, footerY);
        ctx.lineTo(width - padding, footerY);
        ctx.stroke();

        /* Footer uses the same dark/footer logo asset as the existing content snap. */
        const footerLogoImg = await loadLogoImage(FOOTER_LOGO);
        const footerLogoSize = 58;
        const footerLogoBoxSize = 82;
        const footerLogoX = padding;
        const footerLogoBoxY = height - 151;
        const footerLogoY = footerLogoBoxY + (footerLogoBoxSize - footerLogoSize) / 2;

        ctx.save();
        ctx.fillStyle = '#ffffff';
        if (ctx.roundRect) {
            ctx.beginPath();
            ctx.roundRect(
                footerLogoX - 5,
                footerLogoBoxY,
                footerLogoBoxSize,
                footerLogoBoxSize,
                12
            );
            ctx.fill();
        } else {
            ctx.fillRect(
                footerLogoX - 5,
                footerLogoBoxY,
                footerLogoBoxSize,
                footerLogoBoxSize
            );
        }
        ctx.restore();

        if (footerLogoImg && footerLogoImg.naturalWidth) {
            const ratio = footerLogoImg.naturalWidth / Math.max(1, footerLogoImg.naturalHeight);
            const footerLogoW = footerLogoSize;
            const footerLogoH = footerLogoSize / Math.max(0.1, ratio);
            ctx.save();
            ctx.globalAlpha = 1;
            ctx.drawImage(
                footerLogoImg,
                footerLogoX + 7,
                footerLogoY,
                footerLogoW,
                footerLogoH
            );
            ctx.restore();
        }

        ctx.textAlign = 'left';
        ctx.fillStyle = '#e98006';
        ctx.font = '700 30px "Alkatra", cursive';
        ctx.fillText('भजसी भारत .com', footerLogoX + 98, height - 108);

        ctx.fillStyle = '#d8dee8';
        ctx.font = '400 22px "Noto Sans Devanagari", sans-serif';
        ctx.fillText(
            '(संतवाणी • ग्रंथ • हरिनाम • चिंतन • स्तोत्र)',
            footerLogoX + 98,
            height - 76
        );

        ctx.textAlign = 'right';
        ctx.fillStyle = '#f1f5f9';
        ctx.font = '500 21px "Noto Sans Devanagari", sans-serif';
        ctx.fillText(
            'निर्मिती आणि संकलन: भरत रासवे',
            width - padding,
            height - 108
        );

        ctx.fillStyle = '#30c5ad';
        ctx.font = '400 20px "Noto Sans Devanagari", sans-serif';
        ctx.fillText(
            'वेबसाईटला भेट द्या: bhajasibharat.blogspot.com',
            width - padding,
            height - 76
        );

        let blob = null;
        try {
            blob = await new Promise(function(resolve) {
                canvas.toBlob(resolve, 'image/png', 1);
            });
        } catch (error) {
            console.error('Bhajasi exam share image export error:', error);
            alert('फोटो तयार करता आला नाही. कृपया पुन्हा प्रयत्न करा.');
            return;
        }

        if (!blob) {
            alert('फोटो तयार करता आला नाही. कृपया पुन्हा प्रयत्न करा.');
            return;
        }

        const file = new File(
            [blob],
            'bhajasi-prashna.png',
            { type: 'image/png' }
        );

        /* Native/device share sheet only. Never download or open WhatsApp as a fallback. */
        await shareImageFileNative(
            file,
            'भजसी भारत .com — प्रश्न',
            shareText
        );
    }
    async function openExamSource(source) {
        const target=findExamSource(source);
        if(!target){ alert('संबंधित साहित्य सापडले नाही.'); return; }
        setExamSourceReturn(true);
        let sourceDay = 1;
        if (source.entryId) {
            try {
                const sourceContent = await loadWorkContent(target.work, 'saint');
                const sourceEntry = (normalizeContent(sourceContent).entries || []).find(function(entry){
                    return String(entry && entry.id || '') === String(source.entryId);
                });
                if (sourceEntry && sourceEntry.day !== undefined && sourceEntry.day !== null) {
                    sourceDay = Number(sourceEntry.day) || 1;
                }
            } catch (error) {}
        }
        await openWork(target.saint,target.work,sourceDay,target.parentWork,'saint');
        if(source.entryId){
            setTimeout(function(){
                const node=document.querySelector('[data-entry-id="' + source.entryId + '"]');
                if(node) node.scrollIntoView({behavior:'smooth',block:'center'});
            },450);
        }
    }

