    function jumpHomeSection(id) {
        setView('home');
        setTimeout(function() {
            const target = document.getElementById(id);
            if (target) {
                target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
        }, 30);
    }

    function nextDay() {
        if (!selectedWork && !selectedNityaWork) return;
        const total = getTotalDays(selectedWork || selectedNityaWork, selectedContent);
        if (day >= total) return;

        const next = day + 1;
        setDay(next);

        if (selectedWork && selectedSaint) {
            writeProgress(
                makeWorkKey(selectedSaint, selectedWork),
                { day: next, updatedAt: Date.now() }
            );
        }
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function previousDay() {
        if (day <= 1) return;

        const previous = day - 1;
        setDay(previous);

        if (selectedWork && selectedSaint) {
            writeProgress(
                makeWorkKey(selectedSaint, selectedWork),
                { day: previous, updatedAt: Date.now() }
            );
        }
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function onTouchStart(event) {
        if (view !== 'reader' && view !== 'nityaReader') return;
        touchStart.current = event.changedTouches[0].clientX;
    }

    function onTouchEnd(event) {
        if ((view !== 'reader' && view !== 'nityaReader') || touchStart.current === null) return;
        const end = event.changedTouches[0].clientX;
        const distance = end - touchStart.current;

        if (Math.abs(distance) < 55) {
            touchStart.current = null;
            return;
        }

        if (distance < 0) nextDay();
        else previousDay();

        touchStart.current = null;
    }

    function handleShare() {
        const shareData = {
            title: 'भजसी भारत .com — संतवाणी',
            text: 'संतसाहित्याचे शांत वाचन, सार्थ ज्ञानेश्वरी, हरिपाठ, गाथा आणि नित्य पठण.',
            url: SITE_URL
        };

        if (navigator.share) {
            navigator.share(shareData).catch(function() {});
            return;
        }

        if (navigator.clipboard) {
            navigator.clipboard.writeText(SITE_URL)
                .then(function() { alert('भजसी भारत लिंक कॉपी झाली आहे.'); })
                .catch(function() { alert(SITE_URL); });
        } else {
            alert(SITE_URL);
        }
    }

    async function searchContent(query) {
        const q = String(query || '').trim().toLowerCase();
        if (q.length < 2) {
            setSearchResults([]);
            setSearchLoading(false);
            return;
        }

        const metadata = buildMetadataSearch(saints, nitya);
        const quick = metadata.filter(function(item) {
            return [
                item.title,
                item.sub,
                item.saint && item.saint.search,
                item.work && item.work.search,
                item.nityaWork && item.nityaWork.search
            ].filter(Boolean).join(' ').toLowerCase().indexOf(q) >= 0;
        }).slice(0, 20);

        setSearchResults(quick);
        setSearchLoading(true);

        const candidates = metadata.filter(function(item) {
            return (item.type === 'work' || item.type === 'section' || item.type === 'nitya');
        });

        const contentMatches = [];

        await Promise.all(
            candidates.map(async function(item) {
                try {
                    const work = item.work || item.nityaWork;
                    const kind = item.type === 'nitya' ? 'nitya' : 'saint';
                    const content = await loadWorkContent(work, kind);

                    flattenContentForSearch(content).forEach(function(found) {
                        if (found.text && found.text.toLowerCase().indexOf(q) >= 0) {
                            contentMatches.push({
                                type: 'verse',
                                title: (item.title || work.title) + ' • ' + getVerseLabel(found.entry, found.index, work),
                                sub: String(found.entry.text || '').replace(/\s+/g, ' ').slice(0, 100),
                                saint: item.saint || null,
                                work: work,
                                parentWork: item.parentWork || null,
                                nityaWork: item.nityaWork || null,
                                day: Number(found.entry.day || 1)
                            });
                        }
                    });
                } catch (error) {}
            })
        );

        const combined = quick.concat(contentMatches);
        const seen = {};
        const unique = combined.filter(function(item) {
            const key = item.type + '::' + item.title + '::' + item.sub;
            if (seen[key]) return false;
            seen[key] = true;
            return true;
        });

        setSearchResults(unique.slice(0, 30));
        setSearchLoading(false);
    }

    useEffect(function() {
        const timer = setTimeout(function() { searchContent(search); }, 350);
        return function() { clearTimeout(timer); };
    }, [search, saints, nitya]);

    /*
     * The main page is the default landing state.
     * An unfinished exam is represented by the home-page "परीक्षा पूर्ण करा"
     * badge; it must not automatically reopen the question screen after a
     * browser refresh/back-forward restoration. Only an explicit shared-question
     * URL is allowed to open the exam view on load.
     */
    useEffect(function() {
        const hasSharedExamURL = (function() {
            try {
                const params = new URLSearchParams(window.location.search || '');
                const hasQuestionURL = !!(params.get('bhajasiExam') && params.get('bhajasiQuestion') !== null);
                const navigationEntry = window.performance &&
                    typeof window.performance.getEntriesByType === 'function'
                    ? window.performance.getEntriesByType('navigation')[0]
                    : null;
                const isBrowserReload = !!(navigationEntry && navigationEntry.type === 'reload');

                /* A refresh/new browser load must always land on मुख्य.
                   A shared-question link opened as a normal navigation may still
                   intentionally open the shared question. */
                return hasQuestionURL && !isBrowserReload;
            } catch (e) {
                return false;
            }
        })();

        if (!hasSharedExamURL) {
            setView('home');
            setSelectedExam(null);
            setExamQuestions([]);
            setExamQuestionIndex(0);
            setExamAnswers({});
            setExamSubmitted(false);
            setExamResult(null);
            setCertificateName('');
            setCertificatePreview('');
            setCertificateId('');
            setExamSourceReturn(false);
        }

        function handlePageShow(event) {
            if (!event.persisted || hasSharedExamURL) return;
            setView('home');
            setSelectedExam(null);
            setExamQuestions([]);
            setExamQuestionIndex(0);
            setExamAnswers({});
            setExamSubmitted(false);
            setExamResult(null);
            setCertificateName('');
            setCertificatePreview('');
            setCertificateId('');
            setExamSourceReturn(false);
            window.scrollTo({ top: 0, behavior: 'auto' });
        }

        window.addEventListener('pageshow', handlePageShow);
        return function() {
            window.removeEventListener('pageshow', handlePageShow);
        };
    }, []);

    useEffect(function() {
        if (!pariksha || !Array.isArray(pariksha.exams)) return;

        const navigationEntry = window.performance &&
            typeof window.performance.getEntriesByType === 'function'
            ? window.performance.getEntriesByType('navigation')[0]
            : null;
        const isBrowserReload = !!(navigationEntry && navigationEntry.type === 'reload');
        if (isBrowserReload) return;

        const params = new URLSearchParams(window.location.search || '');
        const examId = params.get('bhajasiExam');
        const questionIndex = params.get('bhajasiQuestion');
        if (!examId || questionIndex === null) return;
        openSharedExamQuestion(examId, questionIndex);
    }, [pariksha]);

    function activateSearchResult(item) {
        setSearch('');
        setGlobalSearchOpen(false);

        if (item.type === 'saint') {
            openSaint(item.saint);
            return;
        }
        if (item.type === 'work') {
            handleWorkClick(item.saint, item.work, null);
            return;
        }
        if (item.type === 'section') {
            handleWorkClick(item.saint, item.work, item.parentWork);
            return;
        }
        if (item.type === 'nitya') {
            openWork(null, item.nityaWork, 1, null, 'nitya');
            return;
        }
        if (item.type === 'verse') {
            if (item.nityaWork) {
                openWork(null, item.nityaWork, item.day, null, 'nitya');
            } else {
                openWork(item.saint, item.work, item.day, item.parentWork || null, 'saint');
            }
        }
    }

    const filteredSaints = useMemo(function() {
        const q = search.trim().toLowerCase();
        if (!q || q.length < 2) return saints;

        return saints.filter(function(saint) {
            return [
                saint.name,
                saint.search,
                (saint.works || []).map(function(work) {
                    return [work.title, work.type, work.description, work.search].filter(Boolean).join(' ');
                }).join(' ')
            ].filter(Boolean).join(' ').toLowerCase().indexOf(q) >= 0;
        });
    }, [saints, search]);

    const continueItems = useMemo(function() {
        return getProgressItems(saints);
    }, [saints, selectedContent, view]);

    const filteredGranthWorks = useMemo(function() {
        return topLevelWorks(saints);
    }, [saints]);

    const filteredNityaWorks = useMemo(function() {
        return nitya && Array.isArray(nitya.works) ? nitya.works : [];
    }, [nitya]);

    const themes = [
        { title: 'नामस्मरण', keys: ['नाम', 'हरि', 'हरी', 'राम', 'कृष्ण', 'हरिपाठ'] },
        { title: 'भक्ती', keys: ['भक्ती', 'भक्ति', 'भक्त', 'देव', 'दैवत', 'विठ्ठल', 'पूजा'] },
        { title: 'ज्ञान', keys: ['ज्ञान', 'विवेक', 'आत्म', 'तत्त्व', 'बोध', 'ब्रह्म'] },
        { title: 'समता', keys: ['समता', 'समत्व', 'समदृष्टी', 'सर्वभूती', 'एकत्व', 'भेद', 'पक्षपात', 'समान'] },
        { title: 'सेवा', keys: ['सेवा', 'सेवक', 'दया', 'करुणा', 'परोपकार', 'समाजसेवा', 'लोकसेवा', 'कर्म'] },
        { title: 'वैराग्य', keys: ['वैराग्य', 'विरक्त', 'मोह', 'प्रपंच', 'आसक्ति', 'अनासक्त', 'त्याग'] },
        { title: 'सदाचार', keys: ['सत्य', 'नीती', 'धर्म', 'आचार', 'सदाचार', 'कर्तव्य', 'शुचिता', 'सज्जन'] },
        { title: 'मनःशांती', keys: ['मनःशांती', 'शांत', 'शांती', 'स्थिर', 'चिंता', 'समाधान', 'चित्तशुद्धी', 'चित्तशुद्धि'] }
    ];

    useEffect(function() {
        let cancelled = false;

        async function buildThemeIndex() {
            if (!theme) {
                setThemeMatches([]);
                setThemeLoading(false);
                return;
            }

            setThemeLoading(true);
            const matches = [];
            const seen = {};
            const targets = [];

            saints.forEach(function(saint) {
                (saint.works || []).forEach(function(work) {
                    if (work.file || !workHasSections(work)) {
                        targets.push({ saint: saint, work: work, parentWork: null });
                    }
                    (work.sections || []).forEach(function(section) {
                        targets.push({ saint: saint, work: section, parentWork: work });
                    });
                });
            });

            const metadataHit = function(target, contentText) {
                const text = [
                    target.saint && target.saint.name,
                    target.saint && target.saint.search,
                    target.work && target.work.title,
                    target.work && target.work.type,
                    target.work && target.work.description,
                    target.work && target.work.search,
                    contentText
                ].filter(Boolean).join(' ').toLowerCase();

                return theme.keys.some(function(key) {
                    return text.indexOf(key.toLowerCase()) >= 0;
                });
            };

            const chunkSize = 8;
            for (let i = 0; i < targets.length && !cancelled; i += chunkSize) {
                const chunk = targets.slice(i, i + chunkSize);
                await Promise.all(chunk.map(async function(target) {
                    try {
                        const content = await loadWorkContent(target.work, 'saint');
                        const flat = flattenContentForSearch(content);
                        const contentText = flat.map(function(item) { return item.text; }).join(' ');

                        if (!metadataHit(target, contentText)) return;

                        const key = target.saint.id + '::' +
                            (target.parentWork ? target.parentWork.id || target.parentWork.title + '::' : '') +
                            (target.work.id || target.work.title || target.work.file);
                        if (seen[key]) return;
                        seen[key] = true;

                        matches.push({
                            saint: target.saint,
                            work: target.work,
                            parentWork: target.parentWork,
                            displayTitle: target.work.title,
                            displaySub: target.parentWork ? target.parentWork.title + ' • ' + target.saint.name : target.saint.name
                        });
                    } catch (error) {}
                }));
            }

            if (!cancelled) {
                setThemeMatches(matches);
                setThemeLoading(false);
            }
        }

        buildThemeIndex();

        return function() { cancelled = true; };
    }, [theme, saints]);

    const currentEntries = useMemo(function() {
        if (!selectedContent) return [];
        const raw = getEntriesForDay(selectedContent, day);
        return expandHaripath(
            raw,
            selectedWork ? selectedWork.title : selectedNityaWork ? selectedNityaWork.title : ''
        );
    }, [selectedContent, day, selectedWork, selectedNityaWork]);

    const totalDays = getTotalDays(selectedWork || selectedNityaWork, selectedContent);
    const progressPercent = totalDays <= 1 ? 100 : ((day - 1) / (totalDays - 1)) * 100;

    useEffect(function() {
        if (!globalSearchOpen) return;

        const onKeyDown = function(e) {
            if (e.key === 'Escape') {
                setGlobalSearchOpen(false);
                setSearch('');
            }
        };

        document.addEventListener('keydown', onKeyDown);
        const previousOverflow = document.body.style.overflow;
        document.body.style.overflow = 'hidden';

        return function() {
            document.removeEventListener('keydown', onKeyDown);
            document.body.style.overflow = previousOverflow;
        };
    }, [globalSearchOpen]);

    async function loadCertificateQrImage(url) {
        try {
            if (!window.qrcode) {
                await new Promise(function(resolve,reject){
                    const existing=document.querySelector('script[data-bhajasi-qrcode="1"]');
                    if(existing){
                        if(window.qrcode){resolve();return;}
                        existing.addEventListener('load',resolve,{once:true});
                        existing.addEventListener('error',reject,{once:true});
                        return;
                    }
                    const script=document.createElement('script');
                    script.dataset.bhajasiQrcode='1';
                    script.src='https://cdnjs.cloudflare.com/ajax/libs/qrcode-generator/1.4.4/qrcode.min.js';
                    script.onload=resolve;
                    script.onerror=reject;
                    document.head.appendChild(script);
                });
            }
            if(!window.qrcode) return null;
            const qr=window.qrcode(0,'M');
            qr.addData(String(url));
            qr.make();
            const dataUrl=qr.createDataURL(6,4);
            return await new Promise(function(resolve){
                const img=new Image();
                img.onload=function(){resolve(img);};
                img.onerror=function(){resolve(null);};
                img.src=dataUrl;
            });
        }catch(e){
            console.warn('Certificate QR unavailable:',e);
            return null;
        }
    }

    async function createCertificate() {
        const name=String(certificateName || '').trim().replace(/\\s+/g,' ');
        if(!name){alert('प्रमाणपत्रासाठी तुमचे नाव लिहा.');return;}
        if(!examResult || !examResult.passed || !selectedExam)return;

        const CERTIFICATE_REGISTRY_KEY='bhajasi_certificate_registry_v1';
        const nameKey=name.normalize('NFC').toLocaleLowerCase('mr-IN');
        const registry=safeJSON(localStorage.getItem(CERTIFICATE_REGISTRY_KEY) || '{}',{});
        const existing=registry[nameKey];

        if(existing && existing.examId && existing.examId!==selectedExam.id){
            alert('या नावासाठी एकच डिजिटल प्रमाणपत्र दिले जाऊ शकते. या नावाचे प्रमाणपत्र आधीच उपलब्ध आहे.');
            return;
        }

        const id=(existing && existing.id) || certificateId || makeCertificateId();
        // Certificate content follows the exam currently being taken.
        const certificateSaint=String(selectedExam.subtitle || selectedExam.saint || 'संतवाणी').trim();
        const certificateSubject=String(selectedExam.title || 'ज्ञान परीक्षा').trim();
        const certificateAchievement='यांनी '+certificateSaint+' कृत '+certificateSubject+' विषयावरील ज्ञान परीक्षा उत्तीर्ण केली आहे.';
        const certificateCaption='मी भजसी भारत .com वरील '+certificateSubject+' विषयावरील ज्ञान परीक्षा यशस्वीरीत्या उत्तीर्ण केली.';
        const canvas=document.createElement('canvas');
        canvas.width=1600;
        canvas.height=1100;
        const ctx=canvas.getContext('2d');
        if(!ctx)return;

        const NAME_FONT='700 82px "Kalam", cursive';
        const TITLE_FONT='700 104px "Teko", sans-serif';
        const HEADER_FONT='700 48px "Hind", sans-serif';
        const SUBJECT_FONT='600 43px "Tiro Devanagari Marathi", serif';
        const BODY_FONT='500 29px "Hind", sans-serif';
        const INFO_LABEL_FONT='600 22px "Noto Serif Devanagari", serif';
        const INFO_VALUE_FONT='700 35px "Teko", sans-serif';

        if(document.fonts && document.fonts.ready){
            try{
                await document.fonts.ready;
                await Promise.all([
                    document.fonts.load(TITLE_FONT),
                    document.fonts.load(NAME_FONT),
                    document.fonts.load(HEADER_FONT),
                    document.fonts.load(SUBJECT_FONT),
                    document.fonts.load(BODY_FONT),
                    document.fonts.load(INFO_LABEL_FONT),
                    document.fonts.load(INFO_VALUE_FONT)
                ]);
            }catch(e){}
        }

        function roundedRect(x,y,w,h,r){
            ctx.beginPath();
            if(ctx.roundRect) ctx.roundRect(x,y,w,h,r);
            else ctx.rect(x,y,w,h);
        }

        function fitText(text,font,maxWidth,minSize){
            ctx.font=font;
            let size=parseInt(font.match(/(\\d+)px/)?.[1] || '40',10);
            const floor=minSize || 24;
            while(size>floor){
                ctx.font=font.replace(/\\d+px/,size+'px');
                if(ctx.measureText(text).width<=maxWidth) return ctx.font;
                size-=2;
            }
            return font.replace(/\\d+px/,size+'px');
        }

        function drawSplash(x,y,r,alpha){
            const g=ctx.createRadialGradient(x,y,0,x,y,r);
            g.addColorStop(0,'rgba(251,213,45,'+alpha+')');
            g.addColorStop(.45,'rgba(48,197,173,'+(alpha*.52)+')');
            g.addColorStop(1,'rgba(42,57,80,0)');
            ctx.fillStyle=g;
            ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();
        }

        const bg=ctx.createLinearGradient(0,0,1600,1100);
        bg.addColorStop(0,'#fffaf0');
        bg.addColorStop(.46,'#f7f4ea');
        bg.addColorStop(1,'#eef7f4');
        ctx.fillStyle=bg;ctx.fillRect(0,0,1600,1100);
        drawSplash(180,150,250,.20);
        drawSplash(1420,170,300,.16);
        drawSplash(1340,920,320,.14);
        drawSplash(230,920,280,.12);

        const frame=ctx.createLinearGradient(70,40,1530,1060);
        frame.addColorStop(0,'#e5a928');
        frame.addColorStop(.24,'#fff1a3');
        frame.addColorStop(.48,'#d7a12a');
        frame.addColorStop(.70,'#fff5bd');
        frame.addColorStop(1,'#c98613');
        ctx.strokeStyle=frame;ctx.lineWidth=12;roundedRect(34,34,1532,1032,42);ctx.stroke();

        const inner=ctx.createLinearGradient(80,70,1510,1030);
        inner.addColorStop(0,'#f6d56a');
        inner.addColorStop(.5,'#ffffff');
        inner.addColorStop(1,'#d79a21');
        ctx.strokeStyle=inner;ctx.lineWidth=3;roundedRect(52,52,1496,996,31);ctx.stroke();

        let logoImg=null;
        try{ logoImg=await loadLogoImage(FOOTER_LOGO); }catch(e){}
        // Use the same verified dark UI logo for the certificate watermark, courtesy header and footer.
        // All three are rendered from the canvas-safe decoded image above.

        // Faint branded watermark behind the certificate content.
        if(logoImg && logoImg.naturalWidth){
            const ratio=logoImg.naturalWidth/Math.max(1,logoImg.naturalHeight);
            const wmSize=500;
            const wmW=wmSize;
            const wmH=wmSize/Math.max(.1,ratio);
            ctx.save();
            ctx.globalAlpha=0.095;
            ctx.globalCompositeOperation='multiply';
            ctx.drawImage(logoImg,(1600-wmW)/2,300,wmW,wmH);
            ctx.restore();
        }

        // Header: QR at top-left; centered Bhajasi Bharat courtesy line; exam line below.
        const qrImg=await loadCertificateQrImage('https://bhajasibharat.blogspot.com/');
        if(qrImg && qrImg.naturalWidth){
            const qrBoxX=88, qrBoxY=76, qrBoxSize=126;
            ctx.save();
            ctx.fillStyle='#ffffff';
            roundedRect(qrBoxX,qrBoxY,qrBoxSize,qrBoxSize,14);ctx.fill();
            ctx.strokeStyle='rgba(203,145,30,.72)';ctx.lineWidth=2;ctx.stroke();
            const qrPad=10;
            ctx.drawImage(qrImg,qrBoxX+qrPad,qrBoxY+qrPad,qrBoxSize-qrPad*2,qrBoxSize-qrPad*2);
            ctx.restore();
        }

        ctx.textBaseline='alphabetic';

        // Centered courtesy row: [logo] भजसी भारत .com  सौजन्य
        const courtesy='भजसी भारत .com';
        const courtesyNote='सौजन्य';
        const courtesyLogoSize=62;
        const courtesyGap=18;
        ctx.font='700 44px "Alkatra", cursive';
        const courtesyW=ctx.measureText(courtesy).width;
        ctx.font='600 23px "Hind", sans-serif';
        const noteW=ctx.measureText(courtesyNote).width;
        const courtesyTextW=courtesyW+22+noteW;
        const courtesyGroupW=courtesyLogoSize+courtesyGap+courtesyTextW;
        const courtesyStart=800-courtesyGroupW/2;
        if(logoImg && logoImg.naturalWidth){
            const ratio=logoImg.naturalWidth/Math.max(1,logoImg.naturalHeight);
            const logoW=courtesyLogoSize;
            const logoH=courtesyLogoSize/Math.max(.1,ratio);
            ctx.drawImage(logoImg,courtesyStart,78,logoW,logoH);
        }
        ctx.textAlign='left';
        ctx.fillStyle='#7b5a10';
        ctx.font='700 44px "Alkatra", cursive';
        ctx.fillText(courtesy,courtesyStart+courtesyLogoSize+courtesyGap,108);
        ctx.fillStyle='#59636b';
        ctx.font='600 23px "Hind", sans-serif';
        ctx.fillText(courtesyNote,courtesyStart+courtesyLogoSize+courtesyGap+courtesyW+22,108);

        const headerText='ज्ञान अभ्यास परीक्षा';
        ctx.textAlign='center';
        ctx.fillStyle='#7b5a10';
        ctx.font=HEADER_FONT;
        ctx.fillText(headerText,800,181);

        // Subject: white text on a solid Bhajasi brand-gradient box, with no decorative circles.
        const subjectText=certificateSubject;
        ctx.font='700 48px "Hind", sans-serif';
        const subjectW=Math.min(980,Math.max(650,ctx.measureText('विषय: '+subjectText).width+110));
        const subjectH=78;
        const subjectX=800-subjectW/2;
        const subjectY=207;
        const subjectGrad=ctx.createLinearGradient(subjectX,subjectY,subjectX+subjectW,subjectY+subjectH);
        subjectGrad.addColorStop(0,'#41436A');
        subjectGrad.addColorStop(.48,'#984063');
        subjectGrad.addColorStop(1,'#30c5ad');
        ctx.save();
        ctx.fillStyle=subjectGrad;
        roundedRect(subjectX,subjectY,subjectW,subjectH,20);
        ctx.fill();
        ctx.restore();
        ctx.fillStyle='#ffffff';
        ctx.fillText('विषय: '+subjectText,800,subjectY+52);

        // Main title: Teko inside an elegant rounded box, moved below the subject with clear spacing.
        const titleBoxX=505, titleBoxY=314, titleBoxW=590, titleBoxH=132;
        const titleGrad=ctx.createLinearGradient(titleBoxX,titleBoxY,titleBoxX+titleBoxW,titleBoxY+titleBoxH);
        titleGrad.addColorStop(0,'rgba(255,255,255,.88)');
        titleGrad.addColorStop(.5,'rgba(255,250,230,.96)');
        titleGrad.addColorStop(1,'rgba(245,250,246,.92)');
        ctx.fillStyle=titleGrad;
        roundedRect(titleBoxX,titleBoxY,titleBoxW,titleBoxH,38);ctx.fill();
        ctx.strokeStyle='#d39b24';ctx.lineWidth=4;ctx.stroke();
        ctx.strokeStyle='rgba(229,169,40,.55)';ctx.lineWidth=2;
        roundedRect(titleBoxX+11,titleBoxY+11,titleBoxW-22,titleBoxH-22,29);ctx.stroke();

        ctx.fillStyle='#765311';
        ctx.font=TITLE_FONT;
        ctx.textBaseline='middle';
        ctx.fillText('प्रमाणपत्र',800,380);

        // Certificate body.
        ctx.fillStyle='#58636c';
        ctx.font=BODY_FONT;
        ctx.textBaseline='alphabetic';
        ctx.fillText('प्रमाणित करण्यात येते की,',800,490);

        // Recipient name is always Kalam in PNG/share/PDF.
        ctx.fillStyle='#352b24';
        ctx.font=fitText(name,NAME_FONT,1120,34);
        ctx.fillText(name,800,582);

        const nameWidth=Math.min(900,ctx.measureText(name).width+100);
        const nameLine=ctx.createLinearGradient(800-nameWidth/2,0,800+nameWidth/2,0);
        nameLine.addColorStop(0,'rgba(233,128,6,0)');
        nameLine.addColorStop(.5,'rgba(233,128,6,.72)');
        nameLine.addColorStop(1,'rgba(233,128,6,0)');
        ctx.strokeStyle=nameLine;ctx.lineWidth=2;
        ctx.beginPath();ctx.moveTo(800-nameWidth/2,600);ctx.lineTo(800+nameWidth/2,600);ctx.stroke();

        // Achievement text is derived from the selected exam; never hard-code a saint or subject.
        ctx.fillStyle='#4f5961';
        ctx.font=BODY_FONT;
        ctx.fillText(certificateAchievement,800,667);
        ctx.fillText('करिता हे डिजिटल प्रमाणपत्र प्रदान करण्यात येत आहे.',800,708);

        // Score/date boxes.
        const boxY=760, boxW=330, boxH=126;
        const leftX=285, rightX=985;
        function drawInfoBox(x,title,value){
            const g=ctx.createLinearGradient(x,boxY,x+boxW,boxY+boxH);
            g.addColorStop(0,'rgba(255,255,255,.82)');
            g.addColorStop(.5,'rgba(255,249,226,.92)');
            g.addColorStop(1,'rgba(238,249,245,.88)');
            ctx.fillStyle=g;roundedRect(x,boxY,boxW,boxH,18);ctx.fill();
            ctx.strokeStyle='rgba(203,145,30,.78)';ctx.lineWidth=2;ctx.stroke();
            ctx.fillStyle='#8b6418';ctx.font=INFO_LABEL_FONT;ctx.fillText(title,x+boxW/2,boxY+37);
            ctx.fillStyle='#27343d';ctx.font=INFO_VALUE_FONT;ctx.fillText(value,x+boxW/2,boxY+84);
        }
        drawInfoBox(leftX,'गुण',toMarathiDigits(examResult.score)+' / '+toMarathiDigits(examResult.total)+'  •  '+toMarathiDigits(examResult.percentage)+'%');
        drawInfoBox(rightX,'पूर्णता दिनांक',new Date(examResult.completedAt).toLocaleDateString('mr-IN'));

        // Footer: left information column + horizontally aligned central branding.
        const footerTop=900;
        ctx.strokeStyle='rgba(203,145,30,.42)';ctx.lineWidth=2;
        ctx.beginPath();ctx.moveTo(92,footerTop);ctx.lineTo(1508,footerTop);ctx.stroke();

        ctx.textAlign='left';
        ctx.fillStyle='#4f5961';
        ctx.font='600 18px "Noto Sans Devanagari",sans-serif';
        ctx.fillText('Certificate ID: '+id,110,943);
        ctx.font='500 17px "Noto Sans Devanagari",sans-serif';
        ctx.fillText('https://bhajasibharat.blogspot.com/',110,973);
        ctx.fillText('निर्मिती आणि संकलन: भरत रासवे',110,1003);

        // Right-aligned footer branding: logo + site title + subtitle.
        const footerLogoSize=72;
        const footerLogoBoxSize=84;
        const footerRight=1490;
        const footerTitle='भजसी भारत .com';
        const footerSubtitle='संतवाणी • ग्रंथ • हरिनाम • चिंतन • स्तोत्र';
        ctx.textAlign='left';
        ctx.font='700 46px "Alkatra", cursive';
        const footerTitleW=ctx.measureText(footerTitle).width;
        ctx.font='500 20px "Hind", sans-serif';
        const footerSubtitleW=ctx.measureText(footerSubtitle).width;
        const footerTextW=Math.max(footerTitleW,footerSubtitleW);
        const footerBrandW=footerLogoBoxSize+22+footerTextW;
        const footerBrandX=footerRight-footerBrandW;
        const footerLogoBoxY=934;
        if(logoImg && logoImg.naturalWidth){
            const ratio=logoImg.naturalWidth/Math.max(1,logoImg.naturalHeight);
            const footerW=footerLogoSize;
            const footerH=footerLogoSize/Math.max(.1,ratio);
            ctx.save();
            ctx.fillStyle='#ffffff';
            roundedRect(footerBrandX,footerLogoBoxY,footerLogoBoxSize,footerLogoBoxSize,13);ctx.fill();
            ctx.drawImage(logoImg,footerBrandX+6,footerLogoBoxY+6,footerW,footerH);
            ctx.restore();
        }

        const footerTextX=footerBrandX+footerLogoBoxSize+22;
        ctx.textAlign='right';
        ctx.fillStyle='#7b5a10';
        ctx.font='700 46px "Alkatra", cursive';
        ctx.fillText(footerTitle,footerRight,967);
        ctx.fillStyle='#5d6570';
        ctx.font='500 20px "Hind", sans-serif';
        ctx.fillText(footerSubtitle,footerRight,997);

        registry[nameKey]={
            id:id,
            name:name,
            examId:selectedExam.id,
            completedAt:examResult.completedAt || new Date().toISOString()
        };
        try{localStorage.setItem(CERTIFICATE_REGISTRY_KEY,JSON.stringify(registry));}catch(e){}

        setCertificateId(id);
        setCertificateName(name);
        setCertificatePreview(canvas.toDataURL('image/png',1));
        navigate('certificate');
    }

    async function getCertificateFile(){
        if(!certificatePreview)return null;
        const response=await fetch(certificatePreview);
        const blob=await response.blob();
        return new File([blob],'bhajasi-certificate-'+(certificateId||'completion')+'.png',{type:'image/png'});
    }

    async function shareCertificate(){
        if(!certificatePreview)return;
        try{
            const file=await getCertificateFile();
            const shareSubject=String(selectedExam && selectedExam.title || 'ज्ञान परीक्षा').trim();
            const caption='मी भजसी भारत .com वरील '+shareSubject+' विषयावरील ज्ञान परीक्षा यशस्वीरीत्या उत्तीर्ण केली.\n\nभजसी भारत .com\nhttps://bhajasibharat.blogspot.com/\nनिर्मिती व संकलन: भरत रासवे';
            const shared = await shareImageFileNative(
                file,
                'भजसी भारत .com — '+shareSubject+' ज्ञान परीक्षा प्रमाणपत्र',
                caption
            );
            if(shared) navigate('examResult');
        }catch(error){
            console.error('Certificate share error:',error);
            alert('प्रमाणपत्र शेअर करता आले नाही. कृपया प्रतिमा जतन करून शेअर करा.');
        }
    }

    async function downloadCertificateImage(){
        if(!certificatePreview)return;
        try{
            const file=await getCertificateFile();
            if(!file)throw new Error('certificate file unavailable');
            const url=URL.createObjectURL(file);
            const a=document.createElement('a');a.href=url;a.download=file.name;document.body.appendChild(a);a.click();a.remove();
            setTimeout(function(){URL.revokeObjectURL(url);},1500);
            setTimeout(function(){navigate('examResult');},250);
        }catch(error){alert('प्रतिमा जतन करता आली नाही.');}
    }

    async function downloadCertificatePDF(){
        if(!certificatePreview)return;
        try{
            // Load jsPDF exactly once and wait for the global to be available.
            if(!window.jspdf || !window.jspdf.jsPDF){
                await new Promise(function(resolve,reject){
                    const existing=document.querySelector('script[data-bhajasi-jspdf="1"]');
                    if(existing){
                        if(window.jspdf && window.jspdf.jsPDF){resolve();return;}
                        existing.addEventListener('load',resolve,{once:true});
                        existing.addEventListener('error',reject,{once:true});
                        return;
                    }
                    const script=document.createElement('script');
                    script.dataset.bhajasiJspdf='1';
                    script.src='https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
                    script.onload=resolve;
                    script.onerror=reject;
                    document.head.appendChild(script);
                });
            }

            const JsPDF=window.jspdf && window.jspdf.jsPDF;
            if(!JsPDF)throw new Error('jsPDF unavailable');

            // Use the exact same certificate PNG for PDF so the Kalam name and logo
            // cannot change between PNG, share and PDF.
            const img=await new Promise(function(resolve,reject){
                const image=new Image();
                image.onload=function(){resolve(image);};
                image.onerror=reject;
                image.src=certificatePreview;
            });

            const pdf=new JsPDF({orientation:'landscape',unit:'mm',format:'a4'});
            const pageW=297;
            const pageH=210;
            const imageRatio=img.naturalWidth/Math.max(1,img.naturalHeight);
            const imageW=pageW;
            const imageH=imageW/imageRatio;
            const y=(pageH-imageH)/2;
            pdf.addImage(img,'PNG',0,y,imageW,imageH,undefined,'FAST');
            pdf.setProperties({
                title:'भजसी भारत .com — '+String(selectedExam && selectedExam.title || 'ज्ञान परीक्षा')+' ज्ञान परीक्षा प्रमाणपत्र',
                subject:'डिजिटल प्रमाणपत्र',
                author:'भरत रासवे'
            });
            pdf.save('bhajasi-certificate-'+(certificateId||'completion')+'.pdf');
            setTimeout(function(){navigate('examResult');},250);
        }catch(error){
            console.error('Certificate PDF error:',error);
            alert('PDF तयार करता आला नाही. कृपया पुन्हा प्रयत्न करा.');
        }
    }

