                        </>
                    )}

                    {view === 'pariksha' && (
                        <section className='bhajasi-section bhajasi-section-themes'>
                            <div className='bhajasi-reader-head'><div className='bhajasi-title-row'><h2 className='bhajasi-title'>ज्ञान प्रमाणपत्र परीक्षा</h2></div><p className='bhajasi-meta'>संतसाहित्य आणि ग्रंथांवर आधारित ज्ञानाचा अभ्यास व सराव करा. प्रत्येक प्रश्नासोबत संबंधित साहित्य वाचण्याची संधी आहे. ८०% उत्तीर्ण निकष.</p></div>
                            <div className='bhajasi-grid'>
                                {!pariksha || !Array.isArray(pariksha.exams) || pariksha.exams.length===0 ? <div className='bhajasi-empty'>सध्या कोणतीही परीक्षा उपलब्ध नाही.</div> : pariksha.exams.map(function(exam){
                                    const savedExamProgress = readExamProgress()[exam.id];
                                    const savedExamResult = safeJSON(localStorage.getItem(EXAM_RESULT_KEY) || '{}', {})[exam.id];
                                    const solvedCount = savedExamProgress && savedExamProgress.answers ? Object.keys(savedExamProgress.answers).length : 0;
                                    const hasResume = !!savedExamProgress;
                                    const hasCompleted = !!(savedExamResult && savedExamResult.completedAt);
                                    return (
                                        <article key={exam.id} className='bhajasi-exam-card'>
                                            <div className='bhajasi-card-title'>{exam.title}</div>
                                            <div className='bhajasi-card-sub'>{exam.subtitle}</div>
                                            <div className='bhajasi-exam-meta'>{toMarathiDigits(exam.questionCount||0)} प्रश्न</div>
                                            {hasResume && <div className='bhajasi-meta' style={{color:'#fbd52d',margin:'7px 0 8px'}}>परीक्षा सुरू आहे • {toMarathiDigits(solvedCount)} उत्तरे जतन केली आहेत</div>}
                                            {hasCompleted && <div className='bhajasi-meta' style={{color:'#a7f3d0',margin:'7px 0 8px'}}>परीक्षा पूर्ण • {toMarathiDigits(savedExamResult.score)} / {toMarathiDigits(savedExamResult.total)} • {toMarathiDigits(savedExamResult.percentage)}%</div>}
                                            <button className={'bhajasi-primary-btn'+(hasResume?' bhajasi-resume-btn':'')} onClick={function(){startExam(exam);}}>{hasResume ? 'पुन्हा सुरू करा' : (hasCompleted ? 'पुन्हा परीक्षा द्या' : 'परीक्षा सुरू करा')}</button>
                                        </article>
                                    );
                                })}
                            </div>
                        </section>
                    )}

                    {view === 'exam' && selectedExam && (
                        <section className='bhajasi-section bhajasi-section-works' style={view === 'exam' ? {paddingBottom:'10px'} : {}}>
                            <div className='bhajasi-reader-head'><button className='bhajasi-back' onClick={openParikshaList}>← परीक्षांकडे परत</button><div className='bhajasi-title-row'><h2 className='bhajasi-title'>{selectedExam.title}</h2></div><p className='bhajasi-meta'>प्रश्न {toMarathiDigits(examQuestionIndex+1)} / {toMarathiDigits(examQuestions.length)}</p></div>
                            {examQuestions.length ? (function(){const question=examQuestions[examQuestionIndex];const questionKey=getExamQuestionKey(question,examQuestionIndex);const selectedOption=examAnswers[questionKey];return (
                                <div className='bhajasi-exam-question'><div className='bhajasi-exam-progress'><div className='bhajasi-exam-progress-bar' style={{width:(((examQuestionIndex+1)/examQuestions.length)*100)+'%'}}></div></div><h3>{question.question}</h3>
                                    <div className='bhajasi-exam-options'>{(question.options||[]).map(function(option,optionIndex){const active=Number(selectedOption)===optionIndex;return <button key={optionIndex} className={'bhajasi-exam-option'+(active?' selected':'')} onClick={function(){selectExamAnswer(optionIndex);}}><span className='bhajasi-exam-radio'>{active?'✓':''}</span><span>{option}</span></button>;})}</div>
                                    <div className='bhajasi-exam-actions'><button className='bhajasi-secondary-btn' disabled={examQuestionIndex===0} onClick={function(){changeExamQuestion(examQuestionIndex-1);}}>मागील</button>{examQuestionIndex<examQuestions.length-1?<button className='bhajasi-primary-btn' disabled={selectedOption===undefined} onClick={function(){changeExamQuestion(examQuestionIndex+1);}}>पुढील प्रश्न</button>:<button className='bhajasi-primary-btn' disabled={selectedOption===undefined} onClick={submitExam}>उत्तर तपासा</button>}</div>
                                    {question.study && <div className='bhajasi-study-inline'>{question.study.text && <div className='bhajasi-study-text'>{question.study.text}</div>}<div className='bhajasi-study-actions'><button className='bhajasi-study-btn' onClick={function(){openExamSource(question.study.source);}}><i className='fa-solid fa-book-open'></i> संबंधित साहित्य वाचा</button><button className='bhajasi-exam-share-btn' type='button' onClick={function(){shareExamQuestion(question,examQuestionIndex);}}><i className='fa-solid fa-share-nodes'></i> मित्रांना प्रश्न विचारा</button></div></div>}
                                </div>
                            );})() : <div className='bhajasi-empty'>या परीक्षेसाठी प्रश्न उपलब्ध नाहीत.</div>}
                        </section>
                    )}

                    {view === 'examResult' && selectedExam && examResult && (
                        <section className='bhajasi-section bhajasi-section-themes'><div className='bhajasi-reader-head'><div className='bhajasi-title-row'><h2 className='bhajasi-title'>परीक्षा पूर्ण</h2></div></div>
                            <div className='bhajasi-result-card'><div className='bhajasi-result-topic'>{selectedExam.title}</div><div className='bhajasi-result-score'>{toMarathiDigits(examResult.score)} / {toMarathiDigits(examResult.total)}</div><div className='bhajasi-result-percent'>{toMarathiDigits(examResult.percentage)}%</div><div className={'bhajasi-result-status '+(examResult.passed?'passed':'failed')}>{examResult.passed?'परीक्षा यशस्वीरीत्या पूर्ण':'उत्तीर्ण निकष पूर्ण झाला नाही'}</div></div>

                            <div className='bhajasi-exam-actions'><button className='bhajasi-secondary-btn' onClick={retryExam}>पुन्हा परीक्षा द्या</button>{examResult.passed && selectedExam.certificate && selectedExam.certificate.enabled!==false && <button className='bhajasi-primary-btn' onClick={function(){setCertificatePreview('');setCertificateName('');setCertificateId('');navigate('certificate');}}>प्रमाणपत्र मिळवा</button>}</div>
                        </section>
                    )}

                    {view === 'certificate' && selectedExam && examResult && examResult.passed && (
                        <section className='bhajasi-section bhajasi-section-works'>
                            <div className='bhajasi-reader-head'>
                                <button className='bhajasi-back' onClick={function(){navigate('examResult');}}>← निकालाकडे परत</button>
                                <div className='bhajasi-title-row'><h2 className='bhajasi-title'>प्रमाणपत्र</h2></div>
                            </div>
                            {!certificatePreview ? (
                                <div className='bhajasi-certificate-form'>
                                    <label htmlFor='bhajasi-certificate-name'>प्रमाणपत्रावर दिसावे असे पूर्ण नाव</label>
                                    <input id='bhajasi-certificate-name' value={certificateName} onChange={function(e){setCertificateName(e.target.value);}} placeholder='तुमचे नाव' autoComplete='name'/>
                                    <p>नाव तपासून प्रमाणपत्र घ्या. एका व्यक्तीला एकच प्रमाणपत्र मिळेल.</p>
                                    <button className='bhajasi-primary-btn' onClick={createCertificate}>प्रमाणपत्र घ्या</button>
                                </div>
                            ) : (
                                <div className='bhajasi-certificate-preview'>
                                    <div className='bhajasi-certificate-image-wrap bhajasi-certificate-watermark-preview'>
                                        <img src={certificatePreview} alt='भजसी भारत डिजिटल प्रमाणपत्र'/>
                                    </div>
                                    <div className='bhajasi-certificate-id'>Certificate ID: {certificateId}</div>
                                    <div className='bhajasi-certificate-share-row'>
                                        <button className='bhajasi-primary-btn' onClick={shareCertificate}><i className='fa-solid fa-share-nodes'></i> यश शेअर करा</button>
                                        <button className='bhajasi-secondary-btn' onClick={downloadCertificateImage}><i className='fa-solid fa-image'></i> प्रतिमा जतन करा</button>
                                        <button className='bhajasi-secondary-btn' onClick={downloadCertificatePDF}><i className='fa-solid fa-file-pdf'></i> PDF मिळवा</button>
                                    </div>
                                    <p className='bhajasi-certificate-helper'>प्रतिमा किंवा PDF जतन केल्यानंतर हा प्रमाणपत्र दृश्य बंद होईल.</p>
                                </div>
                            )}
                        </section>
                    )}

                    {/* SAINTS TAB: Matches exact Nitya Pathan reader head format */}
                    {view === 'saints' && (
                        <section className='bhajasi-section bhajasi-section-saints'>
                            <div className='bhajasi-reader-head'>
                                <button className='bhajasi-back' onClick={goHome}>
                                    ← मुख्य पानावर परत
                                </button>
                                <div className='bhajasi-title-row'>
                                    <h2 className='bhajasi-title'>संत आणि महाकवी</h2>
                                </div>
                                <p className='bhajasi-meta'>
                                    महाराष्ट्रातील व भारतातील महान संतांची जीवनगाथा आणि त्यांचे ग्रंथसाहित्य.
                                </p>
                            </div>
                            <div className='bhajasi-grid'>
                                {filteredSaints.length === 0 ? (
                                    <div className='bhajasi-empty'>संत माहिती लोड होत आहे…</div>
                                ) : (
                                    filteredSaints.map(function(saint) {
                                        return (
                                            <button
                                                key={saint.id}
                                                className='bhajasi-card bhajasi-saint-card'
                                                onClick={function() {
                                                    openSaint(saint);
                                                }}
                                            >
                                                <div className='bhajasi-card-title'>
                                                    {saint.name}
                                                </div>
                                                <div className='bhajasi-card-sub'>
                                                    {getSaintCardSummary(saint)}
                                                </div>
                                            </button>
                                        );
                                    })
                                )}
                            </div>
                        </section>
                    )}

                    {/* BOOKS TAB: Matches exact Nitya Pathan reader head format */}
                    {view === 'books' && (
                        <section className='bhajasi-section bhajasi-section-works'>
                            <div className='bhajasi-reader-head'>
                                <button className='bhajasi-back' onClick={goHome}>
                                    ← मुख्य पानावर परत
                                </button>
                                <div className='bhajasi-title-row'>
                                    <h2 className='bhajasi-title'>ग्रंथ संग्रह</h2>
                                </div>
                                <p className='bhajasi-meta'>
                                    सार्थ ज्ञानेश्वरी, तुकाराम गाथा, दासबोध, हरिपाठ व समग्र संत ग्रंथसाहित्य.
                                </p>
                            </div>
                            <div className='bhajasi-grid'>
                                {filteredGranthWorks.length === 0 ? (
                                    <div className='bhajasi-empty'>ग्रंथ साहित्य लोड होत आहे…</div>
                                ) : (
                                    filteredGranthWorks.map(function(item) {
                                        return (
                                            <button
                                                key={item.saint.id + '::' + (item.work.id || item.work.title)}
                                                className='bhajasi-card bhajasi-work-card'
                                                onClick={function() {
                                                    handleWorkClick(item.saint, item.work, null);
                                                }}
                                            >
                                                <div className='bhajasi-card-title'>
                                                    {item.work.title}
                                                </div>
                                                <div className='bhajasi-card-sub'>
                                                    {item.saint.name}
                                                </div>
                                            </button>
                                        );
                                    })
                                )}
                            </div>
                        </section>
                    )}

                    {view === 'works' && selectedSaint && (
                        <section>
                            <div className='bhajasi-reader-head'>
                                <button className='bhajasi-back' onClick={goSaints}>
                                    ← संतांकडे परत
                                </button>
                                <div className='bhajasi-breadcrumb'>
                                    <span>संत</span>
                                    <span>›</span>
                                    <span>{selectedSaint.name}</span>
                                </div>
                                <div className='bhajasi-title-row'>
                                    <h2 className='bhajasi-title'>{selectedSaint.name}</h2>
                                </div>
                            </div>
                            <div className='bhajasi-grid'>
                                {(selectedSaint.works || []).map(function(work, index) {
                                    return (
                                        <button
                                            key={work.id || work.file || index}
                                            className='bhajasi-card bhajasi-work-card'
                                            onClick={function() {
                                                handleWorkClick(selectedSaint, work, null);
                                            }}
                                        >
                                            <div className='bhajasi-card-title'>{work.title}</div>
                                            <div className='bhajasi-card-sub'>{getWorkSummary(work)}</div>
                                        </button>
                                    );
                                })}
                            </div>
                        </section>
                    )}

                    {view === 'sections' && selectedSaint && selectedParentWork && (
                        <section>
                            <div className='bhajasi-reader-head'>
                                <button className='bhajasi-back' onClick={function() { openSaint(selectedSaint); }}>
                                    ← {selectedSaint.name} कडे परत
                                </button>
                                <div className='bhajasi-breadcrumb'>
                                    <span>{selectedSaint.name}</span>
                                    <span>›</span>
                                    <span>{selectedParentWork.title}</span>
                                </div>
                                <div className='bhajasi-title-row'>
                                    <h2 className='bhajasi-title'>{selectedParentWork.title}</h2>
                                </div>
                            </div>
                            <div className='bhajasi-grid'>
                                {(selectedParentWork.sections || []).map(function(section, index) {
                                    const count = section.entries ? section.entries.length : section.verses || section.ovis || '';
                                    return (
                                        <button
                                            key={section.id || section.file || index}
                                            className='bhajasi-card bhajasi-work-card'
                                            onClick={function() {
                                                handleWorkClick(selectedSaint, section, selectedParentWork);
                                            }}
                                        >
                                            <div className='bhajasi-card-title'>
                                                {formatSubTitle(section.title, selectedParentWork.title)}
                                            </div>
                                            <div className='bhajasi-card-sub'>
                                                {getSectionDisplaySubtitle(section)}
                                                {count ? (getSectionDisplaySubtitle(section) ? ' • ' : '') + toMarathiDigits(count) + ' नोंदी' : ''}
                                                {section.days ? ' • दिवस ' + toMarathiDigits(section.days) : ''}
                                            </div>
                                        </button>
                                    );
                                })}
                            </div>
                        </section>
                    )}

                    {view === 'nitya' && (
                        <section className='bhajasi-section bhajasi-section-themes'>
                            <div className='bhajasi-reader-head'>
                                <button className='bhajasi-back' onClick={goHome}>
                                    ← मुख्य पानावर परत
                                </button>
                                <div className='bhajasi-title-row'>
                                    <h2 className='bhajasi-title'>नित्य पठण स्तोत्रे व मंत्र</h2>
                                </div>
                                <p className='bhajasi-meta'>रोजच्या पठणासाठी स्तोत्रे, मंत्र आणि उपलब्ध स्रोतांनुसार अर्थ.</p>
                            </div>
                            <div className='bhajasi-grid'>
                                {nityaWorks.map(function(work, index) {
                                    return (
                                        <button
                                            key={work.id || work.file || index}
                                            className='bhajasi-card bhajasi-work-card bhajasi-nitya-card'
                                            onClick={function() {
                                                openWork(null, work, 1, null, 'nitya');
                                            }}
                                        >
                                            <div className='bhajasi-card-title'>{work.title}</div>
                                            <div className='bhajasi-card-sub'>
                                                {work.type || 'नित्य पठण'}
                                                {work.author ? ' • ' + work.author : ''}
                                            </div>
                                        </button>
                                    );
                                })}
                            </div>
                        </section>
                    )}

                    {(view === 'reader' || view === 'nityaReader') && (
                        <section>
                            <div className='bhajasi-reader-head'>
                                <div className='bhajasi-reader-nav'>
                                    <button
                                        className='bhajasi-back'
                                        onClick={function() {
                                            if (view === 'nityaReader') openNityaList();
                                            else if (selectedParentWork) { setSelectedContent(null); navigate('sections'); }
                                            else openSaint(selectedSaint);
                                        }}
                                    >
                                        ← परत
                                    </button>
                                    <span className='bhajasi-day-label'>
                                        {totalDays > 1 ? 'दिवस ' + toMarathiDigits(day) : (selectedWork && selectedWork.type ? selectedWork.type : 'वाचन')}
                                    </span>
                                </div>

                                <div className='bhajasi-breadcrumb'>
                                    {view === 'reader' ? (
                                        <>
                                            <span>{selectedSaint && selectedSaint.name}</span>
                                            <span>›</span>
                                            {selectedParentWork && (
                                                <>
                                                    <span>{selectedParentWork.title}</span>
                                                    <span>›</span>
                                                </>
                                            )}
                                            <span>{selectedWork && selectedWork.title}</span>
                                        </>
                                    ) : (
                                        <>
                                            <span>नित्य पठण</span>
                                            <span>›</span>
                                            <span>{selectedNityaWork && selectedNityaWork.title}</span>
                                        </>
                                    )}
                                </div>

                                <div className='bhajasi-title-row'>
                                    <h2 className='bhajasi-title'>
                                        {view === 'reader'
                                            ? getReaderTitle(selectedWork, selectedParentWork)
                                            : selectedNityaWork && selectedNityaWork.title}
                                    </h2>
                                </div>
                            </div>

                            {workLoading ? (
                                <div className='bhajasi-empty'>साहित्य लोड होत आहे…</div>
                            ) : currentEntries.length === 0 ? (
                                <div className='bhajasi-empty'>या विभागासाठी साहित्य उपलब्ध नाही.</div>
                            ) : (
                                currentEntries.map(function(entry, index) {
                                    const text = entry.text || entry.original || entry.content || '';
                                    return (
                                        <article
                                            key={(entry.id || 'entry') + '-' + index}
                                            className='bhajasi-verse'
                                            data-entry-id={entry.id || ''}
                                        >
                                            <div className='bhajasi-verse-header'>
                                                <span className='bhajasi-verse-badge'>
                                                    {getVerseLabel(entry, index, selectedWork || selectedNityaWork)}
                                                </span>
                                                <button
                                                    className='bhajasi-verse-wa-btn'
                                                    onClick={function() {
                                                        shareVerseSnap(
                                                            entry,
                                                            index,
                                                            selectedWork || selectedNityaWork,
                                                            selectedSaint,
                                                            selectedParentWork
                                                        );
                                                    }}
                                                    title='या रचनेचा फोटो शेअर करा'
                                                >
                                                    <i className='fa-brands fa-whatsapp'></i>
                                                    फोटो शेअर
                                                </button>
                                            </div>

                                            <div className='bhajasi-verse-text'>
                                                {splitPoem(text).map(function(line, lineIndex) {
                                                    return (
                                                        <span key={lineIndex} className='bhajasi-verse-line'>
                                                            {line}
                                                        </span>
                                                    );
                                                })}
                                            </div>

                                            {(entry.meaning || entry.arth || entry.translation) && (
                                                <div className='bhajasi-meaning'>
                                                    <div className='bhajasi-meaning-title'>भावार्थ</div>
                                                    <p className='bhajasi-meaning-text'>
                                                        {entry.meaning || entry.arth || entry.translation}
                                                    </p>
                                                </div>
                                            )}

                                            {(entry.teaching || entry.shikavan || entry.lesson) && (
                                                <div className='bhajasi-teaching'>
                                                    <div className='bhajasi-teaching-title'>शिकवण</div>
                                                    <p className='bhajasi-teaching-text'>
                                                        {entry.teaching || entry.shikavan || entry.lesson}
                                                    </p>
                                                </div>
                                            )}
                                        </article>
                                    );
                                })
                            )}

                            <div className='bhajasi-reader-footer'>
                                <button
                                    className='bhajasi-pager'
                                    onClick={previousDay}
                                    disabled={day <= 1}
                                    aria-label='मागील दिवस'
                                    title='मागील दिवस'
                                >
                                    <i className='fa-solid fa-chevron-left'></i>
                                </button>
                                <button
                                    className='bhajasi-pager'
                                    onClick={nextDay}
                                    disabled={day >= totalDays}
                                    aria-label='पुढील दिवस'
                                    title='पुढील दिवस'
                                >
                                    <i className='fa-solid fa-chevron-right'></i>
                                </button>
                            </div>
                        </section>
                    )}

                    {view === 'theme' && theme && (
                        <section>
                            <div className='bhajasi-reader-head'>
                                <button className='bhajasi-back' onClick={goHome}>
                                    ← मुख्य पानावर परत
                                </button>
                                <div className='bhajasi-title-row'>
                                    <h2 className='bhajasi-title'>{theme.title}</h2>
                                </div>
                            </div>
                            <div className='bhajasi-grid'>
                                {themeLoading ? (
                                    <div className='bhajasi-theme-loading'>या विषयाशी संबंधित साहित्य शोधत आहे…</div>
                                ) : themeMatches.length === 0 ? (
                                    <div className='bhajasi-empty'>
                                        या विषयाशी संबंधित साहित्य उपलब्ध नाही.
                                    </div>
                                ) : (
                                    themeMatches.map(function(item, index) {
                                        return (
                                            <button
                                                key={(item.work.id || item.work.file || item.displayTitle) + '-' + index}
                                                className='bhajasi-card'
                                                onClick={function() {
                                                    handleWorkClick(item.saint, item.work, item.parentWork);
                                                }}
                                            >
                                                <div className='bhajasi-card-title'>{item.displayTitle}</div>
                                                <div className='bhajasi-card-sub'>{item.displaySub}</div>
                                            </button>
                                        );
                                    })
                                )}
                            </div>
                        </section>
                    )}

                    {loadErrors.length > 0 && (
                        <div className='bhajasi-empty' style={{ marginTop: '18px' }}>
                            काही डेटा फाइल्स लोड करता आल्या नाहीत. कृपया पुन्हा प्रयत्न करा.
                        </div>
                    )}

                    {renderPageFooter()}
                </main>

                {examSourceReturn && (view === 'reader' || view === 'sections') && (
                    <button className='bhajasi-exam-return-float' onClick={function(){setExamSourceReturn(false);navigate('exam');}}>
                        परीक्षेकडे परत <i className='fa-solid fa-arrow-right'></i>
                    </button>
                )}

                <nav className='bhajasi-bottom'>
                    <button className={view === 'home' ? 'active' : ''} onClick={goHome}>
                        <span className='bhajasi-bottom-icon'><i className='fa-solid fa-house'></i></span>
                        मुख्य
                    </button>
                    <button className={view === 'saints' || view === 'works' || view === 'sections' ? 'active' : ''} onClick={goSaints}>
                        <span className='bhajasi-bottom-icon'><i className='fa-solid fa-hands-praying'></i></span>
                        संत
                    </button>
                    <button className={view === 'books' ? 'active' : ''} onClick={function() { openBooks(); }}>
                        <span className='bhajasi-bottom-icon'><i className='fa-solid fa-book'></i></span>
                        ग्रंथ
                    </button>
                    <button className={view === 'nitya' || view === 'nityaReader' ? 'active' : ''} onClick={openNityaList}>
                        <span className='bhajasi-bottom-icon'><i className='fa-solid fa-book-open'></i></span>
                        नित्य पठण
                    </button>
                    <button className={view === 'pariksha' || view === 'exam' || view === 'examResult' || view === 'certificate' ? 'active' : ''} onClick={openParikshaList}>
                        <span className='bhajasi-bottom-icon'><i className='fa-solid fa-award'></i></span>
                        परीक्षा
                    </button>
                </nav>

                {renderGlobalSearchUI()}
            </div>
        </div>
    );
}

/* =========================================================
   IMAGE SHARE — Rebuilt with shiny gradient frame & boxes
========================================================= */
async function loadLogoImage(url) {
    if (!url) return null;

    try {
        const response = await fetch(url, {
            mode: 'cors',
            cache: 'no-store',
            credentials: 'omit'
        });
        if (!response.ok) throw new Error('Logo HTTP ' + response.status);

        const blob = await response.blob();
        const dataUrl = await new Promise(function(resolve, reject) {
            const reader = new FileReader();
            reader.onload = function() { resolve(reader.result); };
            reader.onerror = reject;
            reader.readAsDataURL(blob);
        });

        return await new Promise(function(resolve) {
            const img = new Image();
            img.onload = function() { resolve(img); };
            img.onerror = function() { resolve(null); };
            img.src = dataUrl;
        });
    } catch (error) {
        try {
            return await new Promise(function(resolve) {
                const img = new Image();
                img.crossOrigin = 'anonymous';
                img.onload = function() { resolve(img); };
                img.onerror = function() { resolve(null); };
                img.src = url;
            });
        } catch (e) {
            return null;
        }
    }
}

async function shareImageFileNative(file, title, text) {
    if (!file) return false;

    if (!navigator.share) {
        alert('या ब्राउझरमध्ये डिव्हाइस शेअर सुविधा उपलब्ध नाही. कृपया Android Chrome किंवा समर्थ ब्राउझर वापरा.');
        return false;
    }

    const shareData = {
        title: title || 'भजसी भारत .com',
        text: text || '',
        files: [file]
    };

    /* File sharing must be validated before navigator.share().
       If the browser cannot share the image file, do not silently download it
       or open a WhatsApp URL: the requested action is the native share sheet. */
    if (navigator.canShare) {
        try {
            if (!navigator.canShare({ files: [file] })) {
                alert('या ब्राउझरमध्ये प्रतिमा थेट शेअर करता येत नाही. कृपया Android Chrome मधून प्रयत्न करा.');
                return false;
            }
        } catch (error) {
            console.warn('Bhajasi native file-share validation failed:', error);
            return false;
        }
    }

    try {
        await navigator.share(shareData);
        return true;
    } catch (error) {
        if (error && error.name === 'AbortError') return false;
        console.error('Bhajasi native share error:', error);
        alert('शेअर विंडो उघडता आली नाही. कृपया पुन्हा प्रयत्न करा.');
        return false;
    }
}

async function shareVerseSnap(entry, index, workContext, saintContext, parentWorkContext) {
    const saint = saintContext || null;
    const work = workContext || null;
    const parentWork = parentWorkContext || null;

    const saintTitle = saint && saint.name ? saint.name : 'संतवाणी';
    const workTitle = work && work.title ? work.title : '';
    const parentWorkTitle = parentWork && parentWork.title ? String(parentWork.title).trim() : '';
    const sectionSubtitle = work && work.subtitle ? String(work.subtitle).trim() : '';
    const label = getVerseLabel(entry, index, work);
    const text = String(entry && (entry.text || entry.original || entry.content) || '').trim();
    const meaningText = String(entry && (entry.meaning || entry.arth || entry.translation) || '').trim();
    const teachingText = String(entry && (entry.teaching || entry.shikavan || entry.lesson) || '').trim();

    if (!text) {
        alert('या रचनेसाठी शेअर करण्याजोगा मजकूर उपलब्ध नाही.');
        return;
    }

    const width = 1080;
    const padding = 76;
    const contentWidth = width - padding * 2;
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) {
        alert('फोटो तयार करता आला नाही.');
        return;
    }

    if (document.fonts && document.fonts.ready) {
        try {
            await document.fonts.ready;
            await Promise.all([
                document.fonts.load('700 42px "Tiro Devanagari Marathi"'),
                document.fonts.load('700 42px "Laila"'),
                document.fonts.load('400 30px "Noto Sans Devanagari"'),
                document.fonts.load('700 34px "Noto Serif Devanagari"'),
                document.fonts.load('700 30px "Alkatra"')
            ]);
        } catch (e) {}
    }

    function wrap(textValue, font) {
        if (!textValue) return [];
        ctx.font = font;

        const result = [];
        String(textValue).split(/\r?\n/u).forEach(function(paragraph) {
            const words = paragraph.trim().split(/\s+/u).filter(Boolean);
            let current = '';

            words.forEach(function(word) {
                const candidate = current ? current + ' ' + word : word;

                if (ctx.measureText(candidate).width <= contentWidth) {
                    current = candidate;
                    return;
                }

                if (current) {
                    result.push(current);
                    current = '';
                }

                /* Marathi/Devanagari source can contain long unbreakable runs.
                   Break those by Unicode code point so no canvas line can clip. */
                let chunk = '';
                Array.from(word).forEach(function(char) {
                    const next = chunk + char;
                    if (chunk && ctx.measureText(next).width > contentWidth) {
                        result.push(chunk);
                        chunk = char;
                    } else {
                        chunk = next;
                    }
                });
                current = chunk;
            });

            if (current) result.push(current);
        });

        return result;
    }

    const verseLines = [];
    splitPoem(text).forEach(function(line) {
        wrap(line, '700 42px "Laila", "Noto Serif Devanagari", serif').forEach(function(item) {
            verseLines.push(item);
        });
    });

    const meaningLines = wrap(meaningText, '400 29px "Noto Sans Devanagari", sans-serif');
    const teachingLines = wrap(teachingText, '400 29px "Noto Sans Devanagari", sans-serif');

    const topBlock = 335;
    const verseBlock = Math.max(verseLines.length, 1) * 66;
    const meaningBlock = meaningLines.length ? 115 + meaningLines.length * 48 : 0;
    const teachingBlock = teachingLines.length ? 115 + teachingLines.length * 48 : 0;
    const footerBlock = 205;
    const height = Math.max(
        1200,
        topBlock + verseBlock + meaningBlock + teachingBlock + footerBlock + 90
    );

    canvas.width = width;
    canvas.height = height;

    /* Background */
    const gradient = ctx.createLinearGradient(0, 0, width, height);
    gradient.addColorStop(0, '#2a3950');
    gradient.addColorStop(0.48, '#1e2838');
    gradient.addColorStop(1, '#151d2a');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);

    /* Shiny Gold Gradient Frame */
    const frameGradient = ctx.createLinearGradient(0, 24, width, height - 24);
    frameGradient.addColorStop(0, '#ffcf33');
    frameGradient.addColorStop(0.24, '#f59e0b');
    frameGradient.addColorStop(0.50, '#fff0a3');
    frameGradient.addColorStop(0.72, '#e98006');
    frameGradient.addColorStop(1, '#ffd24a');
    ctx.strokeStyle = frameGradient;
    ctx.lineWidth = 4;
    ctx.beginPath();
    if (ctx.roundRect) {
        ctx.roundRect(18, 18, width - 36, height - 36, 25);
    } else {
        ctx.rect(18, 18, width - 36, height - 36);
    }
    ctx.stroke();

    /* Subtle Inner Border Glow */
    ctx.save();
    ctx.globalAlpha = 0.32;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1;
    ctx.beginPath();
    if (ctx.roundRect) {
        ctx.roundRect(21, 21, width - 42, height - 42, 22);
    } else {
        ctx.rect(21, 21, width - 42, height - 42);
    }
    ctx.stroke();
    ctx.restore();

    /* Load the same two logo assets used by the working Question Snap:
       SITE_LOGO = faint white/light watermark
       FOOTER_LOGO = visible footer logo */
    const watermarkImg = await loadLogoImage(SITE_LOGO);
    const footerLogoImg = await loadLogoImage(FOOTER_LOGO);

    /* Faint Watermark */
    if (watermarkImg && watermarkImg.naturalWidth) {
        const wmSize = 440;
        const ratio = watermarkImg.naturalWidth / Math.max(1, watermarkImg.naturalHeight);
        const wmW = wmSize;
        const wmH = wmSize / Math.max(0.1, ratio);
        ctx.save();
        ctx.globalAlpha = 0.075;
        ctx.globalCompositeOperation = 'screen';
        ctx.drawImage(
            watermarkImg,
            (width - wmW) / 2,
            (height - wmH) / 2 - 35,
            wmW,
            wmH
        );
        ctx.restore();
    }

    /* 1. Metadata-aware header: Saint • parent work */
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = '#e98006';
    ctx.font = '700 38px "Tiro Devanagari Marathi", serif';
    ctx.fillText(
        saintTitle + ((parentWorkTitle || workTitle) ? ' • ' + (parentWorkTitle || workTitle) : ''),
        width / 2,
        105
    );

    /* 2. Metadata title: use title/subtitle exactly as supplied by the saint index. */
    const sectionContextText = parentWorkTitle && workTitle
        ? workTitle + ': ' + (sectionSubtitle || '')
        : getReaderTitle(work, parentWork);
    ctx.textAlign = 'left';
    ctx.font = '700 27px "Noto Sans Devanagari", sans-serif';
    const subLabelW = ctx.measureText(sectionContextText || 'वाचन').width;
    const subBoxW = Math.min(contentWidth, Math.max(360, subLabelW + 52));
    const subBoxH = 58;
    const subBoxX = (width - subBoxW) / 2;
    const subBoxY = 130;

    const labelGradient = ctx.createLinearGradient(subBoxX, subBoxY, subBoxX + subBoxW, subBoxY + subBoxH);
    labelGradient.addColorStop(0, '#f6a80b');
    labelGradient.addColorStop(0.5, '#ffd45a');
    labelGradient.addColorStop(1, '#e98006');
    ctx.strokeStyle = labelGradient;
    ctx.lineWidth = 2.5;
    ctx.fillStyle = 'rgba(65,67,106,.45)';
    ctx.beginPath();
    if (ctx.roundRect) {
        ctx.roundRect(subBoxX, subBoxY, subBoxW, subBoxH, 15);
    } else {
        ctx.rect(subBoxX, subBoxY, subBoxW, subBoxH);
    }
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    ctx.fillText(sectionContextText || 'वाचन', width / 2, subBoxY + 38);

    /* 3. Rचना label: use the exact same pill treatment as भावार्थ/शिकवण. */
    function drawLabelPill(titleText, color, topY) {
        const safeTitle = titleText || '';
        ctx.font = '700 24px "Noto Sans Devanagari", sans-serif';
        const tW = ctx.measureText(safeTitle).width;
        const bW = tW + 42;
        const bH = 46;
        const bX = padding;

        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.fillStyle = 'rgba(42,57,80,0.7)';
        ctx.beginPath();
        if (ctx.roundRect) {
            ctx.roundRect(bX, topY, bW, bH, 15);
        } else {
            ctx.rect(bX, topY, bW, bH);
        }
        ctx.fill();
        ctx.stroke();

        ctx.textAlign = 'left';
        ctx.textBaseline = 'alphabetic';
        ctx.fillStyle = color;
        ctx.fillText(safeTitle, bX + 21, topY + 32);
    }

    drawLabelPill(label || 'रचना', '#e98006', 210);

    ctx.textAlign = 'center';
    let y = 300;

    /* 3. Main Verse (Laila Bold 700) */
    ctx.fillStyle = '#ffffff';
    ctx.font = '700 42px "Laila", "Noto Serif Devanagari", serif';
    verseLines.forEach(function(line) {
        ctx.fillText(line, width / 2, y);
        y += 66;
    });

    /* 4. Section Render (Pill Box on Left for भावार्थ & शिकवण) */
    function drawSectionBox(titleText, sectionLines, color) {
        if (!sectionLines.length) return;

        y += 32;

        ctx.font = '700 24px "Noto Sans Devanagari", sans-serif';
        const tW = ctx.measureText(titleText).width;
        const bW = tW + 42;
        const bH = 46;
        const bX = padding;
        const bY = y - 32;

        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.fillStyle = 'rgba(42,57,80,0.7)';
        ctx.beginPath();
        if (ctx.roundRect) {
            ctx.roundRect(bX, bY, bW, bH, 15);
        } else {
            ctx.rect(bX, bY, bW, bH);
        }
        ctx.fill();
        ctx.stroke();

        ctx.textAlign = 'left';
        ctx.fillStyle = color;
        ctx.fillText(titleText, bX + 21, bY + 32);

        y = bY + bH + 42;

        ctx.fillStyle = '#e8edf4';
        ctx.font = '400 29px "Noto Sans Devanagari", sans-serif';
        sectionLines.forEach(function(line) {
            ctx.fillText(line, padding, y);
            y += 48;
        });
        ctx.textAlign = 'center';
    }

    drawSectionBox('भावार्थ', meaningLines, '#63d6b5');
    drawSectionBox('शिकवण', teachingLines, '#30c5ad');

    /* 5. Footer Strip & Logo Container */
    const footerStripY = height - 196;
    ctx.fillStyle = '#0d1624';
    ctx.fillRect(24, footerStripY, width - 48, 172);

    const footerY = height - 176;
    ctx.strokeStyle = 'rgba(148,163,184,.25)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, footerY);
    ctx.lineTo(width - padding, footerY);
    ctx.stroke();

    const footerLogoSize = 58;
    const footerLogoBoxSize = 82;
    const footerLogoX = padding;
    const footerLogoBoxY = height - 151;
    const footerLogoY = footerLogoBoxY + (footerLogoBoxSize - footerLogoSize) / 2;

    ctx.save();
    ctx.fillStyle = '#ffffff';
    if (ctx.roundRect) {
        ctx.beginPath();
        ctx.roundRect(
            footerLogoX - 5,
            footerLogoBoxY,
            footerLogoBoxSize,
            footerLogoBoxSize,
            12
        );
        ctx.fill();
    } else {
        ctx.fillRect(
            footerLogoX - 5,
            footerLogoBoxY,
            footerLogoBoxSize,
            footerLogoBoxSize
        );
    }
    ctx.restore();

    if (footerLogoImg && footerLogoImg.naturalWidth) {
        const ratio = footerLogoImg.naturalWidth / Math.max(1, footerLogoImg.naturalHeight);
        const footerLogoW = footerLogoSize;
        const footerLogoH = footerLogoSize / Math.max(0.1, ratio);
        ctx.save();
        ctx.globalAlpha = 1;
        ctx.globalCompositeOperation = 'source-over';
        ctx.drawImage(
            footerLogoImg,
            footerLogoX + 7,
            footerLogoY,
            footerLogoW,
            footerLogoH
        );
        ctx.restore();
    }

    ctx.textAlign = 'left';
    ctx.fillStyle = '#e98006';
    ctx.font = '700 30px "Alkatra", cursive';
    ctx.fillText('भजसी भारत .com', footerLogoX + 98, height - 108);

    ctx.fillStyle = '#d8dee8';
    ctx.font = '400 22px "Noto Sans Devanagari", sans-serif';
    ctx.fillText(
        '(संतवाणी • ग्रंथ • हरिनाम • चिंतन • स्तोत्र)',
        footerLogoX + 98,
        height - 76
    );

    ctx.textAlign = 'right';
    ctx.fillStyle = '#f1f5f9';
    ctx.font = '500 21px "Noto Sans Devanagari", sans-serif';
    ctx.fillText(
        'निर्मिती आणि संकलन: भरत रासवे',
        width - padding,
        height - 108
    );

    ctx.fillStyle = '#30c5ad';
    ctx.font = '400 20px "Noto Sans Devanagari", sans-serif';
    ctx.fillText(
        'वेबसाईटला भेट द्या: bhajasibharat.blogspot.com',
        width - padding,
        height - 76
    );

    let blob = null;
    try {
        blob = await new Promise(function(resolve) {
            canvas.toBlob(resolve, 'image/png', 1);
        });
    } catch (error) {
        console.error('Bhajasi share image export error:', error);
        alert('फोटो तयार करता आला नाही. कृपया पुन्हा प्रयत्न करा.');
        return;
    }

    if (!blob) {
        alert('फोटो तयार करता आला नाही. कृपया पुन्हा प्रयत्न करा.');
        return;
    }

    const safeLabel = String(label || 'rachana')
        .replace(/[^\u0900-\u097F\w-]+/g, '-')
        .replace(/-+/g, '-')
        .slice(0, 50);

    const file = new File(
        [blob],
        'bhajasi-' + safeLabel + '.png',
        { type: 'image/png' }
    );

    const shareHeader =
        saintTitle +
        ((parentWorkTitle || workTitle) ? ' • ' + (parentWorkTitle || workTitle) : '') +
        (parentWorkTitle && workTitle
            ? ' • ' + workTitle + ': ' + (sectionSubtitle || '') + (sectionSubtitle ? '.' : '')
            : '');

    const shareCaption =
        shareHeader + '\n' +
        (label || 'रचना') + '\n\n' +
        'भजसी भारत .com (संतवाणी • ग्रंथ • हरिनाम • चिंतन • स्तोत्र)\n\n' +
        'निर्मिती आणि संकलन: भरत रासवे\n' +
        'वेबसाईटला भेट द्या: bhajasibharat.blogspot.com';

    /* Native/device share sheet only. Never download or open WhatsApp as a fallback. */
    await shareImageFileNative(
        file,
        saintTitle + (workTitle ? ' • ' + workTitle : ''),
        shareCaption
    );
}

ReactDOM.createRoot(
    document.getElementById('bhajasi-root')
).render(<App />);

